DG.put("krisnaavtaar/52",{"n":52,"title":"ਜਰਾਸੰਧਿ ਜੁਧ ਕਥਨੰ","title_roman":"Jaraasandhi judh kathnan","page":502,"blocks":[{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":502},{"type":"verse","number":[1029],"number_text":"੧੦੨੯।","page":502,"lines":[{"gurmukhi":"ਇਤ ਰਾਜ ਦਯੋ ਨ੍ਰਿਪ ਕਉ ਜਬ ਹੀ ਉਤ ਕੰਸ ਬਧੂ ਪਿਤ ਪਾਸ ਗਈ।","roman":"It raaj dayo nrip kau jab hee ut kans badhoo pit paas gaee |","meaning_en":"","page":502},{"gurmukhi":"ਅਤਿ ਦੀਨ ਸੁ ਛੀਨ ਮਲੀਨ ਮਹਾ ਮਨ ਕੇ ਦੁਖ ਸੋ ਸੋਈ ਰੋਤ ਭਈ।","roman":"Ati deen su chheen maleen mahaa man ke dukh so soee rot bhaee |","meaning_en":"","page":502},{"gurmukhi":"ਪਤਿ ਭਈਯਨ ਕੇ ਬਧਬੇ ਕੀ ਬ੍ਰਿਥਾ ਜੁ ਹਤੀ ਮਨ ਮੈ ਸੋਈ ਭਾਖ ਦਈ।","roman":"Pati bhaeeyan ke badhbe kee brithaa ju hatee man mai soee bhaakh daee |","meaning_en":"","page":502},{"gurmukhi":"ਸੁਨਿ ਕੈ ਮੁਖ ਤੇ ਤਿਹ ਸੰਧਿ ਜਰਾ ਅਤਿ ਕੋਪ ਕੈ ਆਖ ਸਰੋਜ ਤਈ। ੧੦੨੯।","roman":"Suni kai mukh te tih sandhi jaraa ati kop kai aakh saroj taee | 1029 |","meaning_en":"","page":502}]},{"type":"heading","kind":"speaker","name":"ਜਰਾਸੰਧਿਓ ਬਾਚ","gurmukhi":"ਜਰਾਸੰਧਿਓ ਬਾਚ","roman":"Jaraasandhio baach","meaning_en":"","page":502},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":502},{"type":"verse","number":[1030],"number_text":"੧੦੩੦।","page":502,"lines":[{"gurmukhi":"ਹਰਿ ਹਲਧਰਹਿ ਸੰਘਾਰ ਹੋ ਦੁਹਿਤਾ ਪ੍ਰਤਿ ਕਹਿ ਬੈਨ।","roman":"Hari haldharhi sanghaar ho duhitaa prati kahi bain |","meaning_en":"","page":502},{"gurmukhi":"ਰਾਜਧਾਨੀ ਤੇ ਨਿਸਰਿਯੋ ਮੰਤ੍ਰਿ ਬੁਲਾਏ ਸੈਨ। ੧੦੩੦।","roman":"Raajdhaanee te nisriyo mantri bulaae sain | 1030 |","meaning_en":"","page":502}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":502},{"type":"verse","number":[1031],"number_text":"੧੦੩੧।","page":502,"lines":[{"gurmukhi":"ਦੇਸ ਦੇਸ ਪਰਧਾਨ ਪਠਾਏ। ਨਰਪਤਿ ਸਬ ਦੇਸਨ ਤੇ ਲ੍ਯਾਏ।","roman":"Des des pardhaan pathaae | narapti sab desan te lyaae |","meaning_en":"","page":502},{"gurmukhi":"ਆਇ ਨ੍ਰਿਪਤਿ ਕੋ ਕੀਨ ਜੁਹਾਰੂ। ਦਯੋ ਬਹੁਤੁ ਧਨੁ ਤਿਨ ਉਪਹਾਰੂ। ੧੦੩੧।","roman":"Aai nripti ko keen juhaaroo | dayo bahutu dhanu tin uphaaroo | 1031 |","meaning_en":"","page":502}]},{"type":"verse","number":[1032],"number_text":"੧੦੩੨।","page":502,"lines":[{"gurmukhi":"ਜਰਾਸੰਧਿ ਬਹੁ ਸੁਭਟ ਬੁਲਾਏ। ਭਾਤਿ ਭਾਤਿ ਕੇ ਸਸਤ੍ਰ ਬੰਧਾਏ।","roman":"Jaraasandhi bahu subhat bulaae | bhaati bhaati ke sasatr bandhaae |","meaning_en":"","page":502},{"gurmukhi":"ਗਜ ਬਾਜਨ ਪਰ ਪਾਖਰ ਡਾਰੀ। ਸਿਰ ਪਰ ਕੰਚਨ ਸਿਰੀ ਸਵਾਰੀ। ੧੦੩੨।","roman":"Gaj baajan par paakhar daaree | sir par kanchan siree savaaree | 1032 |","meaning_en":"","page":502}]},{"type":"verse","number":[1033],"number_text":"੧੦੩੩।","page":502,"lines":[{"gurmukhi":"ਪਾਇਕ ਰਥ ਬਹੁਤੇ ਜੁਰਿ ਆਏ। ਭੂਪਤਿ ਆਗੇ ਸੀਸ ਨਿਵਾਏ।","roman":"Paaik rath bahute juri aae | bhoopti aage sees nivaae |","meaning_en":"","page":502},{"gurmukhi":"ਅਪਨੀ ਅਪਨੀ ਮਿਸਲ ਸਭ ਗਏ। ਪਾਤਿ ਜੋਰ ਕਰਿ ਠਾਢੇ ਭਏ। ੧੦੩੩।","roman":"Apnee apnee misal sabh gae | paati jor kari thaadhe bhae | 1033 |","meaning_en":"","page":502}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":502},{"type":"verse","number":[1034],"number_text":"੧੦੩੪।","page":502,"lines":[{"gurmukhi":"ਯਹਿ ਸੈਨਾ ਚਤੁਰੰਗ ਜਰਾਸੰਧਿ ਨ੍ਰਿਪ ਕੀ ਬਨੀ।","roman":"Yahi sainaa chaturang jaraasandhi nrip kee banee |","meaning_en":"","page":502},{"gurmukhi":"ਸਾਜਿਯੋ ਕਵਚ ਨਿਖੰਗ ਧਨੁਖ ਬਾਨੁ ਲੈ ਰਥਿ ਚਢਿਯੋ। ੧੦੩੪।","roman":"Saajiyo kavach nikhang dhanukh baanu lai rathi chadhiyo | 1034 |","meaning_en":"","page":502}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":503},{"type":"verse","number":[1035],"number_text":"੧੦੩੫।","page":503,"lines":[{"gurmukhi":"ਜੋਰਿ ਚਮੂੰ ਸਬ ਮੰਤ੍ਰ ਲੈ ਤਬ ਯੌ ਰਨ ਸਾਜ ਸਮਾਜ ਬਨਾਯੋ।","roman":"Jori chamoon sab mantr lai tab yau ran saaj samaaj banaayo |","meaning_en":"","page":503},{"gurmukhi":"ਤੇਈਸ ਛੂਹਨ ਲੈ ਦਲ ਸੰਗਿ ਬਜਾਇ ਕੈ ਬੰਬ ਤਹਾ ਕਹੁ ਧਾਯੋ।","roman":"Te'ees chhoohan lai dal sangi bajaai kai banb tahaa kahu dhaayo |","meaning_en":"","page":503},{"gurmukhi":"ਬੀਰ ਬਡੇ ਸਮ ਰਾਵਨ ਕੇ ਤਿਨ ਕਉ ਸੰਗ ਲੈ ਮਰਿਬੇ ਕਹੁ ਆਯੋ।","roman":"Beer bade sam raavan ke tin kau sang lai maribe kahu aayo |","meaning_en":"","page":503},{"gurmukhi":"ਮਾਨਹੁ ਕਾਲ ਪ੍ਰਲੈ ਦਿਨ ਬਾਰਿਧ ਫੈਲ ਪਰਿਯੋ ਜਲੁ ਯੌ ਦਲੁ ਛਾਯੋ। ੧੦੩੫।","roman":"Maanhu kaal pralai din baaridh phail pariyo jalu yau dalu chhaayo | 1035 |","meaning_en":"","page":503}]},{"type":"verse","number":[1036],"number_text":"੧੦੩੬।","page":503,"lines":[{"gurmukhi":"ਨਗ ਮਾਨਹੁ ਨਾਗ ਬਡੇ ਤਿਹ ਮੈ ਮਛੁਰੀ ਪੁਨਿ ਪੈਦਲ ਕੀ ਬਲ ਜੇਤੀ।","roman":"Nag maanhu naag bade tih mai machhuree puni paidal kee bal jetee |","meaning_en":"","page":503},{"gurmukhi":"ਚਕ੍ਰ ਮਨੋ ਰਥ ਚਕ੍ਰ ਬਨੇ ਉਪਜੀ ਕਵਿ ਕੈ ਮਨ ਮੈ ਕਹੀ ਤੇਤੀ।","roman":"Chakr mano rath chakr bane upjee kavi kai man mai kahee tetee |","meaning_en":"","page":503},{"gurmukhi":"ਹੈ ਭਏ ਬੋਚਨ ਤੁਲਿ ਮਨੋ ਲਹਰੈ ਬਹਰੈ ਬਰਛੀ ਦੁਤਿ ਸੇਤੀ।","roman":"Hai bhae bochan tuli mano lahrai bahrai barchhee duti setee |","meaning_en":"","page":503},{"gurmukhi":"ਸਿੰਧੁ ਕਿਧੌ ਦਲ ਸੰਧਿ ਜਰਾ ਰਹਿਗੀ ਮਥੁਰ ਜਾ ਤਿਹ ਮਧ ਬਰੇਤੀ। ੧੦੩੬।","roman":"Sindhu kidhau dal sandhi jaraa rahigee mathur jaa tih madh baretee | 1036 |","meaning_en":"","page":503}]},{"type":"verse","number":[1037],"number_text":"੧੦੩੭।","page":503,"lines":[{"gurmukhi":"ਜੋ ਬਲ ਬੰਡ ਬਡੇ ਦਲ ਮੈ ਤਿਹ ਅਗ੍ਰ ਕਥਾ ਮਹਿ ਨਾਮ ਕਹੈ ਹਉ।","roman":"Jo bal band bade dal mai tih agr kathaa mahi naam kahai hau |","meaning_en":"","page":503},{"gurmukhi":"ਜੋ ਸੰਗਿ ਸ੍ਯਾਮ ਲਰੈ ਰਿਸ ਕੈ ਤਿਨ ਕੇ ਜਸ ਕੋ ਮੁਖ ਤੇ ਉਚਰੈ ਹਉ।","roman":"Jo sangi syaam larai ris kai tin ke jas ko mukh te uchrai hau |","meaning_en":"","page":503},{"gurmukhi":"ਜੇ ਬਲਿਭਦ੍ਰ ਕੇ ਸੰਗਿ ਭਿਰੇ ਤਿਨ ਕਉ ਕਥ ਕੈ ਪ੍ਰਭ ਲੋਕ ਰਿਝੈ ਹਉ।","roman":"Je balibhadr ke sangi bhire tin kau kath kai prabh lok rijhai hau |","meaning_en":"","page":503},{"gurmukhi":"ਤ੍ਯਾਗ ਸਭੈ ਗ੍ਰਿਹ ਲਾਲਚ ਕੋ ਹਰਿ ਕੇ ਹਰਿ ਕੇ ਹਰਿ ਕੇ ਗੁਨ ਗੈ ਹਉ। ੧੦੩੭।","roman":"Tyaag sabhai grih laalach ko hari ke hari ke hari ke gun gai hau | 1037 |","meaning_en":"","page":503}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":503},{"type":"verse","number":[1038],"number_text":"੧੦੩੮।","page":503,"lines":[{"gurmukhi":"ਜਦੁਬੀਰਨ ਸਬ ਹੂੰ ਸੁਨੀ ਦੂਤ ਕਹੀ ਜਬ ਆਇ।","roman":"Jadubeeran sab hoon sunee doot kahee jab aai |","meaning_en":"","page":503},{"gurmukhi":"ਮਿਲਿ ਸਬ ਹੂੰ ਨ੍ਰਿਪ ਕੇ ਸਦਨ ਮੰਤ੍ਰ ਬਿਚਾਰਿਯੋ ਜਾਇ। ੧੦੩੮।","roman":"Mili sab hoon nrip ke sadan mantr bichaariyo jaai | 1038 |","meaning_en":"","page":503}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":503},{"type":"verse","number":[1039],"number_text":"੧੦੩੯।","page":503,"lines":[{"gurmukhi":"ਤੇਈਸ ਛੂਹਨ ਲੈ ਦਲ ਸੰਗਿ ਚਢਿਯੋ ਹਮ ਪੈ ਅਤਿ ਹੀ ਭਰਿ ਰੋਹੈ।","roman":"Te'ees chhoohan lai dal sangi chadhiyo ham pai ati hee bhari rohai |","meaning_en":"","page":503},{"gurmukhi":"ਜਾਇ ਲਰੈ ਅਰਿ ਕੇ ਸਮੁਹੇ ਇਹ ਲਾਇਕ ਯਾ ਪੁਰ ਮੈ ਅਬ ਕੋ ਹੈ।","roman":"Jaai larai ari ke samuhe ih laaik yaa pur mai ab ko hai |","meaning_en":"","page":503},{"gurmukhi":"ਜੋ ਭਜਿ ਹੈ ਡਰੁ ਮਾਨਿ ਘਨੋ ਰਿਸ ਕੈ ਸਬ ਕੋ ਤਬ ਮਾਰਤ ਸੋ ਹੈ।","roman":"Jo bhaji hai daru maani ghano ris kai sab ko tab maarat so hai |","meaning_en":"","page":503},{"gurmukhi":"ਤਾ ਤੇ ਨਿਸੰਕ ਭਿਰੋ ਇਨ ਸੋ ਜਿਤ ਹੈ ਤੁ ਭਲੋ ਮ੍ਰਿਤ ਏ ਜਸੁ ਹੋ ਹੈ। ੧੦੩੯।","roman":"Taa te nisank bhiro in so jit hai tu bhalo mrit e jasu ho hai | 1039 |","meaning_en":"","page":503}]},{"type":"verse","number":[1040],"number_text":"੧੦੪੦।","page":503,"lines":[{"gurmukhi":"ਤਉ ਜਦੁਬੀਰ ਕਹਿਯੋ ਉਠਿ ਕੈ ਰਿਸਿ ਬੀਚ ਸਭਾ ਅਪੁਨੇ ਬਲ ਸੋ।","roman":"Tau jadubeer kahiyo uthi kai risi beech sabhaa apune bal so |","meaning_en":"","page":503},{"gurmukhi":"ਅਬ ਕੋ ਬਲਵੰਡ ਬਡੋ ਹਮ ਮੈ ਚਲਿ ਆਗੇ ਹੀ ਜਾਇ ਲਰੈ ਦਲ ਸੋ।","roman":"Ab ko balvand bado ham mai chali aage hee jaai larai dal so |","meaning_en":"","page":503},{"gurmukhi":"ਅਪਨੋ ਬਲ ਧਾਰਿ ਸੰਘਾਰ ਕੈ ਦਾਨਵ ਦੂਰ ਕਰੈ ਸਭ ਭੂ ਤਲ ਸੋ।","roman":"Apno bal dhaari sanghaar kai daanav door karai sabh bhoo tal so |","meaning_en":"","page":503},{"gurmukhi":"ਬਹੁ ਭੂਤ ਪਿਸਾਚਨ ਕਾਕਨਿ ਡਾਕਨਿ ਤੋਖ ਕਰੈ ਪਲ ਮੈ ਪਲ ਸੋ। ੧੦੪੦।","roman":"Bahu bhoot pisaachan kaakni daakni tokh karai pal mai pal so | 1040 |","meaning_en":"","page":503}]},{"type":"verse","number":[1041],"number_text":"੧੦੪੧।","page":503,"lines":[{"gurmukhi":"ਜਬ ਯਾ ਬਿਧਿ ਸੋ ਜਦੁਬੀਰ ਕਹਿਯੋ ਕਿਨਹੂੰ ਮਨ ਮੈ ਨਹੀ ਧੀਰ ਧਰਿਯੋ।","roman":"Jab yaa bidhi so jadubeer kahiyo kinhoon man mai nahee dheer dhariyo |","meaning_en":"","page":503},{"gurmukhi":"ਹਰਿ ਦੇਖਿ ਤਬੈ ਮੁਖਿ ਬਾਇ ਰਹੇ ਸਭ ਹੂੰ ਭਜਬੇ ਕਹੁ ਚਿਤ ਕਰਿਯੋ।","roman":"Hari dekhi tabai mukhi baai rahe sabh hoon bhajbe kahu chit kariyo |","meaning_en":"","page":503},{"gurmukhi":"ਜੋਊ ਮਾਨ ਹੁਤੋ ਮਨਿ ਛਤ੍ਰਿਨ ਕੇ ਸੋਊ ਓਰਨਿ ਕੀ ਸਮ ਤੁਲ ਗਰਿਯੋ।","roman":"Jo'oo maan huto mani chhatrin ke so'oo orni kee sam tul gariyo |","meaning_en":"","page":503},{"gurmukhi":"ਕੋਊ ਜਾਇ ਨ ਸਾਮੁਹੈ ਸਤ੍ਰਨ ਕੇ ਨ੍ਰਿਪ ਨੇ ਮੁਖ ਤੇ ਬਿਧਿ ਯਾ ਉਚਰਿਯੋ। ੧੦੪੧।","roman":"Ko'oo jaai na saamuhai satran ke nrip ne mukh te bidhi yaa uchriyo | 1041 |","meaning_en":"","page":503}]},{"type":"verse","number":[1042],"number_text":"੧੦੪੨।","page":504,"lines":[{"gurmukhi":"ਕਿਨਹੂੰ ਨਹਿ ਧੀਰਜੁ ਬਾਧਿ ਸਕਿਯੋ ਲਰਬੇ ਤੇ ਡਰੇ ਸਭ ਕੋ ਮਨੁ ਭਾਜਿਯੋ।","roman":"Kinhoon nahi dheerju baadhi sakiyo larbe te dare sabh ko manu bhaajiyo |","meaning_en":"","page":504},{"gurmukhi":"ਭਾਜਨ ਕੀ ਸਬ ਹੂੰ ਬਿਧ ਕੀ ਕਿਨ ਹੂੰ ਨਹੀ ਕੋਪਿ ਸਰਾਸਨੁ ਸਾਜਿਯੋ।","roman":"Bhaajan kee sab hoon bidh kee kin hoon nahee kopi saraasnu saajiyo |","meaning_en":"","page":504},{"gurmukhi":"ਯੌ ਹਰਿ ਜੂ ਪੁਨਿ ਬੋਲਿ ਉਠਿਓ ਗਜ ਕੋ ਬਧਿ ਕੈ ਜਿਮ ਕੇਹਰਿ ਗਾਜਿਯੋ।","roman":"Yau hari joo puni boli uthio gaj ko badhi kai jim kehri gaajiyo |","meaning_en":"","page":504},{"gurmukhi":"ਅਉਰ ਭਲੀ ਉਪਮਾ ਉਪਜੀ ਧੁਨਿ ਕੋ ਸੁਨ ਕੈ ਘਨ ਸਾਵਨ ਲਾਜਿਯੋ। ੧੦੪੨।","roman":"Aur bhalee upmaa upjee dhuni ko sun kai ghan saavan laajiyo | 1042 |","meaning_en":"","page":504}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":504},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":504},{"type":"verse","number":[1043],"number_text":"੧੦੪੩।","page":504,"lines":[{"gurmukhi":"ਰਾਜ ਨ ਚਿੰਤ ਕਰੋ ਮਨ ਮੈ ਹਮਹੂੰ ਦੋਊ ਭ੍ਰਾਤ ਸੁ ਜਾਇ ਲਰੈਗੇ।","roman":"Raaj na chint karo man mai hamhoon do'oo bhraat su jaai laraige |","meaning_en":"","page":504},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਕੈ ਰਨ ਭੀਤਰ ਜੁਧ ਕਰੈਗੇ।","roman":"Baan kamaan kripaan gadaa gahi kai ran bheetar judh karaige |","meaning_en":"","page":504},{"gurmukhi":"ਜੋ ਹਮ ਊਪਰਿ ਕੋਪ ਕੈ ਆਇ ਹੈ ਤਾਹਿ ਕੇ ਅਸਤ੍ਰ ਸਿਉ ਪ੍ਰਾਨ ਹਰੈਗੇ।","roman":"Jo ham oopri kop kai aai hai taahi ke asatr siu praan haraige |","meaning_en":"","page":504},{"gurmukhi":"ਪੈ ਉਨ ਕੋ ਮਰਿ ਹੈ ਡਰ ਹੈ ਨਹੀ ਆਹਵ ਤੇ ਪਗ ਦੁਇ ਨ ਟਰੈਗੇ। ੧੦੪੩।","roman":"Pai un ko mari hai dar hai nahee aahav te pag dui na taraige | 1043 |","meaning_en":"","page":504}]},{"type":"verse","number":[1044],"number_text":"੧੦੪੪।","page":504,"lines":[{"gurmukhi":"ਇਉ ਕਹਿ ਕੈ ਯੌ ਦੋਊ ਠਾਢ ਭਏ ਚਲ ਕੈ ਨਿਜੁ ਮਾਤ ਪਿਤਾ ਪਹਿ ਆਏ।","roman":"Iu kahi kai yau do'oo thaadh bhae chal kai niju maat pitaa pahi aae |","meaning_en":"","page":504},{"gurmukhi":"ਆਵਤ ਹੀ ਦੁਹੂੰ ਹਾਥਨ ਜੋਰਿ ਕੈ ਪਾਇਨ ਊਪਰ ਮਾਥ ਲੁਡਾਏ।","roman":"Aavat hee duhoon haathan jori kai paain oopar maath ludaae |","meaning_en":"","page":504},{"gurmukhi":"ਮੋਹੁ ਬਢਿਯੋ ਬਸੁਦੇਵ ਅਉ ਦੇਵਕੀ ਲੈ ਅਪੁਨੇ ਸੁਤ ਕੰਠਿ ਲਗਾਏ।","roman":"Mohu badhiyo basudev au devkee lai apune sut kanthi lagaae |","meaning_en":"","page":504},{"gurmukhi":"ਜੀਤਹੁਗੇ ਤੁਮ ਦੈਤਨ ਸਿਉ ਭਜਿ ਹੈ ਅਰਿ ਜ੍ਯੋ ਘਨ ਬਾਤ ਉਡਾਏ। ੧੦੪੪।","roman":"Jeethuge tum daitan siu bhaji hai ari jyo ghan baat udaae | 1044 |","meaning_en":"","page":504}]},{"type":"verse","number":[1045],"number_text":"੧੦੪੫।","page":504,"lines":[{"gurmukhi":"ਮਾਤ ਪਿਤਾ ਕਉ ਪ੍ਰਨਾਮ ਦੋਊ ਕਰਿ ਕੈ ਤਜਿ ਧਾਮ ਸੁ ਬਾਹਰਿ ਆਏ।","roman":"Maat pitaa kau pranaam do'oo kari kai taji dhaam su baahri aae |","meaning_en":"","page":504},{"gurmukhi":"ਆਵਤ ਹੀ ਸਭ ਆਯੁਧ ਲੈ ਪੁਰ ਬੀਰ ਜਿਤੇ ਸਭ ਹੀ ਸੁ ਬੁਲਾਏ।","roman":"Aavat hee sabh aayudh lai pur beer jite sabh hee su bulaae |","meaning_en":"","page":504},{"gurmukhi":"ਦਾਨ ਘਨੇ ਦਿਜ ਕਉ ਦਏ ਸ੍ਯਾਮ ਦੁਹੂੰ ਮਿਲਿ ਆਨੰਦ ਚਿਤ ਬਢਾਏ।","roman":"Daan ghane dij kau dae syaam duhoon mili aanand chit badhaae |","meaning_en":"","page":504},{"gurmukhi":"ਆਸਿਖ ਦੇਤ ਭਏ ਦਿਜ ਇਉ ਗ੍ਰਿਹ ਆਇ ਹੋ ਜੀਤਿ ਘਨੇ ਅਰਿ ਘਾਏ। ੧੦੪੫।","roman":"Aasikh det bhae dij iu grih aai ho jeeti ghane ari ghaae | 1045 |","meaning_en":"","page":504}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":504},{"type":"verse","number":[1046],"number_text":"੧੦੪੬।","page":504,"lines":[{"gurmukhi":"ਦੇਖਿ ਚਮੂੰ ਸਭ ਜਾਦਵੀ ਹਰਿ ਜੂ ਅਪੁਨੇ ਸਾਥ।","roman":"Dekhi chamoon sabh jaadvee hari joo apune saath |","meaning_en":"","page":504},{"gurmukhi":"ਘਨ ਸੁਰ ਸਿਉ ਸੰਗ ਸਾਰਥੀ ਬੋਲਿਯੋ ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ। ੧੦੪੬।","roman":"Ghan sur siu sang saarthee boliyo sree brijnaath | 1046 |","meaning_en":"","page":504}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ ਦਾਰੁਕ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ ਦਾਰੁਕ ਸੋ","roman":"Kaanh joo baach daaruk so","meaning_en":"","page":504},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":504},{"type":"verse","number":[1047],"number_text":"੧੦੪੭।","page":504,"lines":[{"gurmukhi":"ਹਮਰੋ ਰਥ ਦਾਰੁਕ ਤੈ ਕਰਿ ਸਾਜ ਭਲੀ ਬਿਧਿ ਸਿਉ ਅਬ ਤਾ ਰਨ ਕਉ।","roman":"Hamro rath daaruk tai kari saaj bhalee bidhi siu ab taa ran kau |","meaning_en":"","page":504},{"gurmukhi":"ਅਸਿ ਤਾ ਮਹਿ ਚਕ੍ਰ ਗਦਾ ਧਰੀਯੋ ਰਿਪੁ ਕੀ ਧੁਜਨੀ ਸੁ ਬਿਦਾਰਨ ਕਉ।","roman":"Asi taa mahi chakr gadaa dhareeyo ripu kee dhujnee su bidaaran kau |","meaning_en":"","page":504},{"gurmukhi":"ਸਬ ਜਾਦਵ ਲੈ ਅਪਨੇ ਸੰਗ ਹਉ ਸੁ ਪਧਾਰਤ ਦੈਤ ਸੰਘਾਰਨ ਕਉ।","roman":"Sab jaadav lai apne sang hau su padhaarat dait sanghaaran kau |","meaning_en":"","page":504},{"gurmukhi":"ਕਿਹ ਹੇਤ ਚਲਿਯੋ ਸੁਨ ਲੈ ਹਮ ਪੈ ਅਪੁਨੇ ਨ੍ਰਿਪ ਕੇ ਦੁਖ ਟਾਰਨ ਕਉ। ੧੦੪੭।","roman":"Kih het chaliyo sun lai ham pai apune nrip ke dukh taaran kau | 1047 |","meaning_en":"","page":504}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":505},{"type":"verse","number":[1048],"number_text":"੧੦੪੮।","page":505,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਗੋਬਿੰਦ ਤਬਿ ਕਟ ਸਿਉ ਕਸਿਯੋ ਨਿਖੰਗ।","roman":"Yau kahi kai gobind tabi kat siu kasiyo nikhang |","meaning_en":"","page":505},{"gurmukhi":"ਹਲ ਮੂਸਲ ਹਲਧਰਿ ਗਹਿਯੋ ਕਛੁ ਜਾਦਵ ਲੈ ਸੰਗਿ। ੧੦੪੮।","roman":"Hal moosal haladhri gahiyo kachhu jaadav lai sangi | 1048 |","meaning_en":"","page":505}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":505},{"type":"verse","number":[1049],"number_text":"੧੦੪੯।","page":505,"lines":[{"gurmukhi":"ਦੈਤਨ ਮਾਰਨ ਹੇਤ ਚਲੇ ਅਪੁਨੇ ਸੰਗ ਲੈ ਸਭ ਹੀ ਭਟ ਦਾਨੀ।","roman":"Daitan maaran het chale apune sang lai sabh hee bhat daanee |","meaning_en":"","page":505},{"gurmukhi":"ਸ੍ਰੀ ਬਲਿਭਦ੍ਰਹਿ ਸੰਗ ਲਏ ਜਿਹ ਕੇ ਬਲ ਕੀ ਗਤਿ ਸ੍ਰੀ ਪਤਿ ਜਾਨੀ।","roman":"Sree balibhdrahi sang lae jih ke bal kee gati sree pati jaanee |","meaning_en":"","page":505},{"gurmukhi":"ਕੋ ਸਮ ਭੀਖਮ ਹੈ ਇਨ ਕੇ ਅਰੁ ਕੋ ਭ੍ਰਿਗੁ ਨੰਦਨੁ ਰਾਵਨੁ ਬਾਨੀ।","roman":"Ko sam bheekham hai in ke aru ko bhrigu nandnu raavnu baanee |","meaning_en":"","page":505},{"gurmukhi":"ਸਤ੍ਰਨ ਕੇ ਬਧ ਕਾਰਨ ਸ੍ਯਾਮ ਚਲੇ ਮੁਸਲੀ ਧਰਿ ਜੂ ਅਭਿਮਾਨੀ। ੧੦੪੯।","roman":"Satran ke badh kaaran syaam chale muslee dhari joo abhimaanee | 1049 |","meaning_en":"","page":505}]},{"type":"verse","number":[1050],"number_text":"੧੦੫੦।","page":505,"lines":[{"gurmukhi":"ਬਾਧਿ ਕ੍ਰਿਪਾਨ ਸਰਾਸਨ ਲੈ ਚੜਿ ਸਯੰਦਨ ਪੈ ਜਦੁਬੀਰ ਸਿਧਾਰੇ।","roman":"Baadhi kripaan saraasan lai chari sayandan pai jadubeer sidhaare |","meaning_en":"","page":505},{"gurmukhi":"ਭਾਖਤ ਬੈਨ ਸੁਧਾ ਮੁਖ ਤੇ ਸੁ ਕਹਾ ਹੈ ਸਭੈ ਸੁਤ ਬੰਧ ਹਮਾਰੇ।","roman":"Bhaakhat bain sudhaa mukh te su kahaa hai sabhai sut bandh hamaare |","meaning_en":"","page":505},{"gurmukhi":"ਸ੍ਰੀ ਪ੍ਰਭ ਪਾਇਨ ਕੇ ਸਬ ਸਾਥ ਸੁ ਯੌ ਕਹਿ ਕੈ ਇਕ ਬੀਰ ਪੁਕਾਰੇ।","roman":"Sree prabh paain ke sab saath su yau kahi kai ik beer pukaare |","meaning_en":"","page":505},{"gurmukhi":"ਧਾਇ ਪਰੇ ਅਰਿ ਕੇ ਦਲ ਮੈ ਬਲਿ ਸਿਉ ਬਲਿਦੇਵ ਹਲਾਯੁਧ ਧਾਰੇ। ੧੦੫੦।","roman":"Dhaai pare ari ke dal mai bali siu balidev halaayudh dhaare | 1050 |","meaning_en":"","page":505}]},{"type":"verse","number":[1051],"number_text":"੧੦੫੧।","page":505,"lines":[{"gurmukhi":"ਦੇਖਤ ਹੀ ਅਰਿ ਕੀ ਪਤਨਾ ਹਰਿ ਜੂ ਮਨ ਮੋ ਅਤਿ ਕੋਪ ਭਰੇ।","roman":"Dekhat hee ari kee patnaa hari joo man mo ati kop bhare |","meaning_en":"","page":505},{"gurmukhi":"ਸੁ ਧਵਾਇ ਤਹਾ ਰਥੁ ਜਾਇ ਪਰੇ ਧੁਜਨੀ ਪਤ ਤੇ ਨਹੀ ਨੈਕੁ ਡਰੇ।","roman":"Su dhavaai tahaa rathu jaai pare dhujnee pat te nahee naiku dare |","meaning_en":"","page":505},{"gurmukhi":"ਸਿਤ ਬਾਨਨ ਸੋ ਗਜ ਬਾਜ ਹਨੇ ਜੋਊ ਸਾਜ ਜਰਾਇਨ ਸਾਥ ਜਰੇ।","roman":"Sit baanan so gaj baaj hane jo'oo saaj jaraain saath jare |","meaning_en":"","page":505},{"gurmukhi":"ਮਨੋ ਇੰਦ੍ਰ ਕੇ ਬਜ੍ਰ ਲਗੇ ਟੁਟ ਕੈ ਧਰਨੀ ਗਿਰ ਸ੍ਰਿੰਗ ਸੁਮੇਰ ਪਰੇ। ੧੦੫੧।","roman":"Mano indr ke bajr lage tut kai dharnee gir sring sumer pare | 1051 |","meaning_en":"","page":505}]},{"type":"verse","number":[1052],"number_text":"੧੦੫੨।","page":505,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਸਰਾਸਨ ਤੇ ਬਹੁ ਤੀਰ ਛੁਟੇ ਛੁਟ ਕੈ ਭਟ ਘਾਏ।","roman":"Sree jadubeer saraasan te bahu teer chhute chhut kai bhat ghaae |","meaning_en":"","page":505},{"gurmukhi":"ਪੈਦਲ ਮਾਰਿ ਰਥੀ ਬਿਰਥੀ ਕਰਿ ਸਤ੍ਰ ਘਨੇ ਜਮ ਲੋਕਿ ਪਠਾਏ।","roman":"Paidal maari rathee birthee kari satr ghane jam loki pathaae |","meaning_en":"","page":505},{"gurmukhi":"ਭਾਜਿ ਅਨੇਕ ਗਏ ਰਨ ਤੇ ਜੋਊ ਲਾਜ ਭਰੇ ਹਰਿ ਪੈ ਪੁਨਿ ਆਏ।","roman":"Bhaaji anek gae ran te jo'oo laaj bhare hari pai puni aae |","meaning_en":"","page":505},{"gurmukhi":"ਤੇ ਬ੍ਰਿਜਨਾਥ ਕੇ ਹਾਥ ਲਗੇ ਗ੍ਰਿਹ ਕਉ ਫਿਰਿ ਜੀਵਤ ਜਾਨ ਨ ਪਾਏ। ੧੦੫੨।","roman":"Te brijnaath ke haath lage grih kau phiri jeevat jaan na paae | 1052 |","meaning_en":"","page":505}]},{"type":"verse","number":[1053],"number_text":"੧੦੫੩।","page":505,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਰਨ ਮੈ ਭਟ ਯੌ ਚਹੂੰ ਓਰਨ ਤੇ ਲਲਕਾਰ ਪਰੇ।","roman":"Kop bhare ran mai bhat yau chahoon oran te lalkaar pare |","meaning_en":"","page":505},{"gurmukhi":"ਕਰਿ ਚਉਪ ਭਿਰੇ ਅਪਨੇ ਮਨ ਮੈ ਨੰਦ ਨੰਦਨ ਤੇ ਨ ਰਤੀ ਕੁ ਡਰੇ।","roman":"Kari chaup bhire apne man mai nand nandan te na ratee ku dare |","meaning_en":"","page":505},{"gurmukhi":"ਤਬ ਹੀ ਬ੍ਰਿਜਨਾਥ ਸਰਾਸਨ ਲੈ ਛਿਨ ਮੈ ਉਨ ਕੇ ਅਭਿਮਾਨ ਹਰੇ।","roman":"Tab hee brijnaath saraasan lai chhin mai un ke abhimaan hare |","meaning_en":"","page":505},{"gurmukhi":"ਜੋਊ ਆਵਤ ਭੇ ਧਨ ਬਾਨ ਧਰੇ ਹਰਿ ਜੂ ਸਿਗਰੇ ਬਿਨੁ ਪ੍ਰਾਣ ਕਰੇ। ੧੦੫੩।","roman":"Jo'oo aavat bhe dhan baan dhare hari joo sigre binu praan kare | 1053 |","meaning_en":"","page":505}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":505},{"type":"verse","number":[1054],"number_text":"੧੦੫੪।","page":505,"lines":[{"gurmukhi":"ਸ੍ਰਉਨਤ ਤਰੰਗਨੀ ਉਠਤ ਕੋਪਿ ਬਲ ਬੀਰ","roman":"Sraunat tarangnee uthat kopi bal beer","meaning_en":"","page":505},{"gurmukhi":"ਮਾਰਿ ਮਾਰਿ ਤੀਰ ਰਿਪੁ ਖੰਡ ਕੀਏ ਰਨ ਮੈ।","roman":"Maari maari teer ripu khand kee'e ran mai |","meaning_en":"","page":505},{"gurmukhi":"ਬਾਜ ਗਜ ਮਾਰੇ ਰਥੀ ਬ੍ਰਿਥੀ ਕਰਿ ਡਾਰੇ","roman":"Baaj gaj maare rathee brithee kari daare","meaning_en":"","page":505},{"gurmukhi":"ਕੇਤੇ ਪੈਦਲ ਬਿਦਾਰੇ ਸਿੰਘ ਜੈਸੇ ਮ੍ਰਿਗ ਬਨ ਮੈ।","roman":"Kete paidal bidaare singh jaise mrig ban mai |","meaning_en":"","page":505},{"gurmukhi":"ਜੈਸੇ ਸਿਵ ਕੋਪ ਕੈ ਜਗਤ ਜੀਵ ਮਾਰਿ ਪ੍ਰਲੈ","roman":"Jaise siv kop kai jagat jeev maari pralai","meaning_en":"","page":506},{"gurmukhi":"ਤੈਸੇ ਹਰਿ ਅਰਿ ਯੌ ਸੰਘਾਰੇ ਆਈ ਮਨ ਮੈ।","roman":"Taise hari ari yau sanghaare aaee man mai |","meaning_en":"","page":506},{"gurmukhi":"ਏਕ ਮਾਰਿ ਡਾਰੇ ਏਕ ਘਾਇ ਛਿਤਿ ਪਾਰੇ","roman":"Ek maari daare ek ghaai chhiti paare","meaning_en":"","page":506},{"gurmukhi":"ਏਕ ਤ੍ਰਸੇ ਏਕ ਹਾਰੇ ਜਾ ਕੇ ਤਾਕਤ ਨ ਤਨ ਮੈ। ੧੦੫੪।","roman":"Ek trase ek haare jaa ke taakat na tan mai | 1054 |","meaning_en":"","page":506}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":506},{"type":"verse","number":[1055],"number_text":"੧੦੫੫।","page":506,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਘਨਿ ਸ੍ਯਾਮ ਘਨ ਸੁਰ ਕੈ ਬਰਖਿਯੋ ਸਰ ਬੂੰਦਨ ਜਿਉ ਮਗਵਾ।","roman":"Bahuro ghani syaam ghan sur kai barkhiyo sar boondan jiu magvaa |","meaning_en":"","page":506},{"gurmukhi":"ਚਤੁਰੰਗ ਚਮੂੰ ਹਨਿ ਸ੍ਰਉਨ ਬਹਿਯੋ ਸੁ ਭਇਓ ਰਨ ਈਗਰ ਕੇ ਰੰਗਵਾ।","roman":"Chaturang chamoon hani sraun bahiyo su bhaio ran eegar ke rangvaa |","meaning_en":"","page":506},{"gurmukhi":"ਕਹੂੰ ਮੁੰਡ ਝਰੇ ਰਥ ਪੁੰਜ ਢਰੇ ਗਜ ਸੁੰਡ ਪਰੇ ਕਹੂੰ ਹੈ ਤੰਗਵਾ।","roman":"Kahoon mund jhare rath punj dhare gaj sund pare kahoon hai tangvaa |","meaning_en":"","page":506},{"gurmukhi":"ਜਦੁਬੀਰ ਜੁ ਕੋਪ ਕੈ ਤੀਰ ਹਨੇ ਕਹੂੰ ਬੀਰ ਗਿਰੇ ਸੁ ਕਹੂੰ ਅੰਗਵਾ। ੧੦੫੫।","roman":"Jadubeer ju kop kai teer hane kahoon beer gire su kahoon angvaa | 1055 |","meaning_en":"","page":506}]},{"type":"verse","number":[1056],"number_text":"੧੦੫੬।","page":506,"lines":[{"gurmukhi":"ਬਹੁ ਜੂਝਿ ਪਰੇ ਛਿਤ ਪੈ ਭਟ ਯੌ ਅਰਿ ਕੈ ਬਰ ਕੈ ਹਰਿ ਸਿਉ ਲਰਿ ਕੈ।","roman":"Bahu joojhi pare chhit pai bhat yau ari kai bar kai hari siu lari kai |","meaning_en":"","page":506},{"gurmukhi":"ਧਨੁ ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਪਾਨਿ ਗਿਰੇ ਰਨ ਬੀਚ ਇਤੀ ਕਰਿ ਕੈ।","roman":"Dhanu baan kripaan gadaa gahi paani gire ran beech itee kari kai |","meaning_en":"","page":506},{"gurmukhi":"ਤਿਹ ਮਾਸ ਗਿਰਾਸ ਮਵਾਸ ਉਦਾਸ ਹੁਇ ਗੀਧ ਸੁ ਮੋਨ ਰਹੀ ਧਰਿ ਕੈ।","roman":"Tih maas giraas mavaas udaas hui geedh su mon rahee dhari kai |","meaning_en":"","page":506},{"gurmukhi":"ਸੁ ਮਨੋ ਬੁਟੀਆ ਬਰ ਬੀਰਨ ਕੀ ਨ ਪਚੀ ਉਰ ਮੈ ਬਰਿ ਕੈ ਫਰਿਕੈ। ੧੦੫੬।","roman":"Su mano buteeaa bar beeran kee na pachee ur mai bari kai pharikai | 1056 |","meaning_en":"","page":506}]},{"type":"verse","number":[1057],"number_text":"੧੦੫੭।","page":506,"lines":[{"gurmukhi":"ਅਸਿ ਕੋਪਿ ਹਲਾਯੁਧ ਪਾਨਿ ਲੀਯੋ ਸੁ ਧਸਿਯੋ ਦਲ ਮੈ ਅਤਿ ਰੋਸ ਭਰਿਯੋ।","roman":"Asi kopi halaayudh paani leeyo su dhasiyo dal mai ati ros bhariyo |","meaning_en":"","page":506},{"gurmukhi":"ਬਹੁ ਬੀਰ ਹਨੇ ਰਨ ਭੂਮਿ ਬਿਖੈ ਪ੍ਰਤਨਾਪਤਿ ਤੇ ਨ ਰਤੀ ਕੁ ਡਰਿਯੋ।","roman":"Bahu beer hane ran bhoomi bikhai pratnaapti te na ratee ku dariyo |","meaning_en":"","page":506},{"gurmukhi":"ਗਜ ਬਾਜ ਰਥੀ ਅਰੁ ਪਤਿ ਚਮੂੰ ਹਨਿ ਕੈ ਉਨ ਬੀਰਨ ਤੇਜ ਹਰਿਯੋ।","roman":"Gaj baaj rathee aru pati chamoon hani kai un beeran tej hariyo |","meaning_en":"","page":506},{"gurmukhi":"ਜਿਮ ਤਾਤ ਧਰਾ ਸੁਰਪਤਿ ਲਰਿਯੋ ਹਰਿ ਭ੍ਰਾਤ ਬਲੀ ਇਮ ਜੁਧ ਕਰਿਯੋ। ੧੦੫੭।","roman":"Jim taat dharaa surapti lariyo hari bhraat balee im judh kariyo | 1057 |","meaning_en":"","page":506}]},{"type":"verse","number":[1058],"number_text":"੧੦੫੮।","page":506,"lines":[{"gurmukhi":"ਜੁਧ ਜੁਰੇ ਜਦੁਰਾਇ ਸਖਾ ਕਿਧੋ ਕ੍ਰੋਧ ਭਰੇ ਦੁਰਜੋਧਨ ਸੋਹੈ।","roman":"Judh jure jaduraai sakhaa kidho krodh bhare durjodhan sohai |","meaning_en":"","page":506},{"gurmukhi":"ਭੀਰ ਪਰੇ ਰਨਿ ਰਾਵਨ ਸੋ ਸੁਤ ਰਾਵਨ ਕੋ ਤਿਹ ਕੀ ਸਮ ਕੋ ਹੈ।","roman":"Bheer pare rani raavan so sut raavan ko tih kee sam ko hai |","meaning_en":"","page":506},{"gurmukhi":"ਭੀਖਮ ਸੋ ਮਰਬੇ ਕਹੁ ਹੈ ਲਰਿਬੇ ਕਹੁ ਰਾਮ ਬਲੀ ਬਰਿ ਜੋ ਹੈ।","roman":"Bheekham so marbe kahu hai laribe kahu raam balee bari jo hai |","meaning_en":"","page":506},{"gurmukhi":"ਅੰਗਦ ਹੈ ਕਿ ਹਨੂ ਜਮੁ ਹੈ ਕਿ ਭਰਿਯੋ ਬਲਿਭਦ੍ਰ ਭਯਾਨਕ ਰੋਹੈ। ੧੦੫੮।","roman":"Angad hai ki hanoo jamu hai ki bhariyo balibhadr bhayaanak rohai | 1058 |","meaning_en":"","page":506}]},{"type":"verse","number":[1059],"number_text":"੧੦੫੯।","page":506,"lines":[{"gurmukhi":"ਦ੍ਰਿੜ ਕੈ ਬਲਿ ਕੋਪਿ ਹਲਾਯੁਧ ਲੈ ਅਰਿ ਕੇ ਦਲ ਭੀਤਰ ਧਾਇ ਗਯੋ।","roman":"Drir kai bali kopi halaayudh lai ari ke dal bheetar dhaai gayo |","meaning_en":"","page":506},{"gurmukhi":"ਗਜ ਬਾਜ ਰਥੀ ਬਿਰਥੀ ਕਰਿ ਕੈ ਬਹੁ ਪੈਦਲ ਕੋ ਦਲੁ ਕੋਪਿ ਛਯੋ।","roman":"Gaj baaj rathee birthee kari kai bahu paidal ko dalu kopi chhayo |","meaning_en":"","page":506},{"gurmukhi":"ਕਲਿ ਨਾਰਦ ਭੂਤ ਪਿਸਾਚ ਘਨੇ ਸਿਵ ਰੀਝ ਰਹਿਯੋ ਰਨ ਦੇਖਿ ਨਯੋ।","roman":"Kali naarad bhoot pisaach ghane siv reejh rahiyo ran dekhi nayo |","meaning_en":"","page":507},{"gurmukhi":"ਅਰਿ ਯੌ ਸਟਕੇ ਮ੍ਰਿਗ ਕੇ ਗਨ ਜ੍ਯੋ ਮੁਸਲੀਧਰਿ ਮਾਨਹੁ ਸਿੰਘ ਭਯੋ। ੧੦੫੯।","roman":"Ari yau satke mrig ke gan jyo musleedhri maanhu singh bhayo | 1059 |","meaning_en":"","page":507}]},{"type":"verse","number":[1060],"number_text":"੧੦੬੦।","page":507,"lines":[{"gurmukhi":"ਇਕ ਓਰਿ ਹਲਾਯੁਧ ਜੁਧ ਕਰੈ ਇਕ ਓਰਿ ਗੋਬਿੰਦਹ ਖਗ ਸੰਭਾਰਿਯੋ।","roman":"Ik ori halaayudh judh karai ik ori gobindah khag sanbhaariyo |","meaning_en":"","page":507},{"gurmukhi":"ਬਾਜ ਰਥੀ ਗਜਪਤਿ ਹਨੇ ਅਤਿ ਰੋਸ ਭਰੇ ਦਲ ਕੋ ਲਲਕਾਰਿਯੋ।","roman":"Baaj rathee gajapti hane ati ros bhare dal ko lalkaariyo |","meaning_en":"","page":507},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਗਦਾ ਗਹਿ ਸ੍ਰੀ ਹਰਿ ਸੈਥਨ ਸਿਉ ਅਰਿ ਪੁੰਜ ਬਿਡਾਰਿਯੋ।","roman":"Baan kamaan gadaa gahi sree hari saithan siu ari punj bidaariyo |","meaning_en":"","page":507},{"gurmukhi":"ਮਾਰੁਤ ਹ੍ਵੈ ਘਨ ਸ੍ਯਾਮ ਕਿਧੋ ਉਮਡਿਯੋ ਦਲ ਪਾਵਸ ਮੇਘ ਨਿਵਾਰਿਯੋ। ੧੦੬੦।","roman":"Maarut hvai ghan syaam kidho umdiyo dal paavas megh nivaariyo | 1060 |","meaning_en":"","page":507}]},{"type":"verse","number":[1061],"number_text":"੧੦੬੧।","page":507,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਨੰਦ ਲਾਲ ਸਦਾ ਰਿਪੁ ਘਾਲ ਕਰਾਲ ਬਿਸਾਲ ਸਬੈ ਧਨੁ ਲੀਨੋ।","roman":"Sree nand laal sadaa ripu ghaal karaal bisaal sabai dhanu leeno |","meaning_en":"","page":507},{"gurmukhi":"ਇਉ ਸਰ ਜਾਲ ਚਲੇ ਤਿਹ ਕਾਲ ਤਬੈ ਅਰਿ ਸਾਲ ਰਿਸੈ ਇਹ ਕੀਨੋ।","roman":"Iu sar jaal chale tih kaal tabai ari saal risai ih keeno |","meaning_en":"","page":507},{"gurmukhi":"ਘਾਇਨ ਸੰਗਿ ਗਿਰੀ ਚਤੁਰੰਗ ਚਮੂੰ ਸਭ ਕੋ ਤਨ ਸ੍ਰਉਨਤ ਭੀਨੋ।","roman":"Ghaain sangi giree chaturang chamoon sabh ko tan sraunat bheeno |","meaning_en":"","page":507},{"gurmukhi":"ਮਾਨਹੁ ਪੰਦ੍ਰਸਵੋ ਬਿਧ ਨੇ ਸੁ ਰਚਿਯੋ ਰੰਗ ਆਰੁਨ ਲੋਕ ਨਵੀਨੋ। ੧੦੬੧।","roman":"Maanhu pandrasvo bidh ne su rachiyo rang aarun lok naveeno | 1061 |","meaning_en":"","page":507}]},{"type":"verse","number":[1062],"number_text":"੧੦੬੨।","page":507,"lines":[{"gurmukhi":"ਬ੍ਰਿਜ ਭੂਖਨ ਦੂਖਨ ਦੈਤਨ ਕੇ ਰਿਪੁ ਸਾਥ ਰਿਸੈ ਅਤਿ ਮਾਨ ਭਰਿਯੋ।","roman":"Brij bhookhan dookhan daitan ke ripu saath risai ati maan bhariyo |","meaning_en":"","page":507},{"gurmukhi":"ਸੁ ਧਵਾਇ ਤਹਾ ਰਥ ਜਾਇ ਪਰਿਯੋ ਲਖਿ ਦਾਨਵ ਸੈਨ ਨ ਨੈਕੁ ਡਰਿਯੋ।","roman":"Su dhavaai tahaa rath jaai pariyo lakhi daanav sain na naiku dariyo |","meaning_en":"","page":507},{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਅਯੋਧਨ ਮੈ ਹਰਿ ਕੇਹਰਿ ਕੀ ਬਿਧਿ ਜਿਉ ਬਿਚਰਿਯੋ।","roman":"Dhanu baan sanbhaari ayodhan mai hari kehri kee bidhi jiu bichriyo |","meaning_en":"","page":507},{"gurmukhi":"ਭੁਜ ਦੰਡ ਅਦੰਡਨ ਖੰਡਨ ਕੈ ਰਿਸ ਕੈ ਦਲ ਖੰਡਨਿ ਖੰਡ ਕਰਿਯੋ। ੧੦੬੨।","roman":"Bhuj dand adandan khandan kai ris kai dal khandni khand kariyo | 1062 |","meaning_en":"","page":507}]},{"type":"verse","number":[1063],"number_text":"੧੦੬੩।","page":507,"lines":[{"gurmukhi":"ਮਧੁ ਸੂਦਨ ਬੀਚ ਅਯੋਧਨ ਕੇ ਬਹੁਰੋ ਕਰ ਮੈ ਧਨੁ ਬਾਨ ਲਯੋ।","roman":"Madhu soodan beech ayodhan ke bahuro kar mai dhanu baan layo |","meaning_en":"","page":507},{"gurmukhi":"ਸੁ ਨਿਸੰਕ ਤਬੈ ਰਨ ਬੀਚ ਪਰਿਯੋ ਅਰਿ ਕੋ ਬਰ ਕੈ ਹਨਿ ਸੈਨ ਦਯੋ।","roman":"Su nisank tabai ran beech pariyo ari ko bar kai hani sain dayo |","meaning_en":"","page":507},{"gurmukhi":"ਧਨੁ ਸੋ ਜਿਮ ਤੂਲਿ ਧੁਨੈ ਧੁਨੀਯਾ ਦਲ ਤ੍ਯੋ ਸਿਤ ਬਾਨਨ ਸੋ ਧੁਨਿਯੋ।","roman":"Dhanu so jim tooli dhunai dhuneeyaa dal tyo sit baanan so dhuniyo |","meaning_en":"","page":507},{"gurmukhi":"ਬਹੁ ਸ੍ਰਉਨ ਪ੍ਰਵਾਹ ਬਹਿਯੋ ਰਨ ਮੈ ਤਿਹ ਠਾ ਮਨੋ ਆਠਵੋ ਸਿੰਧੁ ਭਯੋ। ੧੦੬੩।","roman":"Bahu sraun pravaah bahiyo ran mai tih thaa mano aathvo sindhu bhayo | 1063 |","meaning_en":"","page":507}]},{"type":"verse","number":[1064],"number_text":"੧੦੬੪।","page":507,"lines":[{"gurmukhi":"ਇਤ ਤੇ ਹਰਿ ਕੀ ਉਮਡੀ ਪ੍ਰਤਨਾ ਉਤ ਤੇ ਉਮਡਿਯੋ ਨ੍ਰਿਪ ਲੈ ਬਲ ਸੰਗਾ।","roman":"It te hari kee umdee pratnaa ut te umdiyo nrip lai bal sangaa |","meaning_en":"","page":507},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਲੈ ਪਾਨਿ ਭਿਰੇ ਕਟਿ ਗੇ ਭਟਿ ਅੰਗ ਪ੍ਰਤੰਗਾ।","roman":"Baan kamaan kripaan lai paani bhire kati ge bhati ang pratangaa |","meaning_en":"","page":507},{"gurmukhi":"ਪਤਿ ਗਿਰੇ ਗਜਿ ਬਾਜ ਕਹੂੰ ਕਹੂੰ ਬੀਰ ਗਿਰੇ ਤਿਨ ਕੇ ਕਹੂੰ ਅੰਗਾ।","roman":"Pati gire gaji baaj kahoon kahoon beer gire tin ke kahoon angaa |","meaning_en":"","page":507},{"gurmukhi":"ਐਸੇ ਗਏ ਮਿਲਿ ਆਪਸਿ ਮੈ ਦਲ ਜੈਸੇ ਮਿਲੇ ਜਮੁਨਾ ਅਰੁ ਗੰਗਾ। ੧੦੬੪।","roman":"Aise gae mili aapsi mai dal jaise mile jamunaa aru gangaa | 1064 |","meaning_en":"","page":507}]},{"type":"verse","number":[1065],"number_text":"੧੦੬੫।","page":507,"lines":[{"gurmukhi":"ਸ੍ਵਾਮਿ ਕੇ ਕਾਜ ਕਉ ਲਾਜ ਭਰੇ ਦੁਹੂੰ ਓਰਨ ਤੇ ਭਟ ਯੌ ਉਮਗੇ ਹੈ।","roman":"Svaami ke kaaj kau laaj bhare duhoon oran te bhat yau umge hai |","meaning_en":"","page":507},{"gurmukhi":"ਜੁਧੁ ਕਰਿਯੋ ਰਨ ਕੋਪਿ ਦੁਹੂੰ ਰਸ ਰੁਦ੍ਰ ਹੀ ਕੇ ਪੁਨਿ ਸੰਗ ਪਗੇ ਹੈ।","roman":"Judhu kariyo ran kopi duhoon ras rudr hee ke puni sang page hai |","meaning_en":"","page":507},{"gurmukhi":"ਜੂਝਿ ਪਰੇ ਸਮੁਹੇ ਲਰਿ ਕੈ ਰਨ ਕੀ ਛਿਤ ਤੇ ਨਹੀ ਪੈਗ ਭਗੇ ਹੈ।","roman":"Joojhi pare samuhe lari kai ran kee chhit te nahee paig bhage hai |","meaning_en":"","page":507},{"gurmukhi":"ਉਜਲ ਗਾਤ ਮੈ ਸਾਗ ਲਗੀ ਮਨੋ ਚੰਦਨ ਰੂਖ ਮੈ ਨਾਗ ਲਗੇ ਹੈ। ੧੦੬੫।","roman":"Ujal gaat mai saag lagee mano chandan rookh mai naag lage hai | 1065 |","meaning_en":"","page":507}]},{"type":"verse","number":[1066],"number_text":"੧੦੬੬।","page":508,"lines":[{"gurmukhi":"ਜੁਧੁ ਕਰਿਯੋ ਰਿਸ ਆਪਸਿ ਮੈ ਦੁਹੂੰ ਓਰਨ ਤੇ ਨਹੀ ਕੋਊ ਟਰੇ।","roman":"Judhu kariyo ris aapsi mai duhoon oran te nahee ko'oo tare |","meaning_en":"","page":508},{"gurmukhi":"ਬਰਛੀ ਗਹਿ ਬਾਨ ਕਮਾਨ ਗਦਾ ਅਸਿ ਲੈ ਕਰ ਮੈ ਇਹ ਭਾਤਿ ਟਰੇ।","roman":"Barchhee gahi baan kamaan gadaa asi lai kar mai ih bhaati tare |","meaning_en":"","page":508},{"gurmukhi":"ਕੋਊ ਜੂਝਿ ਗਿਰੇ ਕੋਊ ਰੀਝਿ ਭਿਰੇ ਛਿਤਿ ਦੇਖਿ ਡਰੇ ਕੋਊ ਧਾਇ ਪਰੇ।","roman":"Ko'oo joojhi gire ko'oo reejhi bhire chhiti dekhi dare ko'oo dhaai pare |","meaning_en":"","page":508},{"gurmukhi":"ਮਨਿ ਯੌ ਉਪਜੀ ਉਪਮਾ ਰਨ ਦੀਪ ਕੇ ਊਪਰ ਆਇ ਪਤੰਗ ਜਰੇ। ੧੦੬੬।","roman":"Mani yau upjee upmaa ran deep ke oopar aai patang jare | 1066 |","meaning_en":"","page":508}]},{"type":"verse","number":[1067],"number_text":"੧੦੬੭।","page":508,"lines":[{"gurmukhi":"ਪ੍ਰਿਥਮੇ ਸੰਗਿ ਬਾਨ ਕਮਾਨ ਭਿਰਿਯੋ ਬਰਛੀ ਬਰ ਲੈ ਪੁਨਿ ਭ੍ਰਾਤ ਮੁਰਾਰੀ।","roman":"Prithme sangi baan kamaan bhiriyo barchhee bar lai puni bhraat muraaree |","meaning_en":"","page":508},{"gurmukhi":"ਫੇਰਿ ਲਰਿਯੋ ਅਸਿ ਲੈ ਕਰ ਮੈ ਧਸ ਕੈ ਰਿਪੁ ਕੀ ਬਹੁ ਸੈਨ ਸੰਘਾਰੀ।","roman":"Pheri lariyo asi lai kar mai dhas kai ripu kee bahu sain sanghaaree |","meaning_en":"","page":508},{"gurmukhi":"ਫੇਰਿ ਗਦਾ ਗਹਿ ਕੈ ਸੁ ਹਤੇ ਬਹੁਰੋ ਜੁ ਹੁਤੇ ਗਹਿ ਪਾਨਿ ਕਟਾਰੀ।","roman":"Pheri gadaa gahi kai su hate bahuro ju hute gahi paani kataaree |","meaning_en":"","page":508},{"gurmukhi":"ਐਚਤ ਯੌ ਹਲ ਸੋ ਦਲ ਕੋ ਜਿਮ ਖੈਚਤ ਦੁਇ ਕਰਿ ਝੀਵਰ ਜਾਰੀ। ੧੦੬੭।","roman":"Aichat yau hal so dal ko jim khaichat dui kari jheevar jaaree | 1067 |","meaning_en":"","page":508}]},{"type":"verse","number":[1068],"number_text":"੧੦੬੮।","page":508,"lines":[{"gurmukhi":"ਜੋ ਭਟ ਸਾਮੁਹੇ ਆਇ ਅਰਿਯੋ ਬਰ ਕੈ ਹਰਿ ਜੂ ਸੋਊ ਮਾਰਿ ਗਿਰਾਯੋ।","roman":"Jo bhat saamuhe aai ariyo bar kai hari joo so'oo maari giraayo |","meaning_en":"","page":508},{"gurmukhi":"ਲਾਜ ਭਰੇ ਜੋਊ ਜੋਰਿ ਭਿਰੇ ਤਿਨ ਤੇ ਕੋਊ ਜੀਵਤ ਜਾਨ ਨ ਪਾਯੋ।","roman":"Laaj bhare jo'oo jori bhire tin te ko'oo jeevat jaan na paayo |","meaning_en":"","page":508},{"gurmukhi":"ਪੈਠਿ ਤਬੈ ਪ੍ਰਤਨਾ ਅਰਿ ਕੀ ਮਧਿ ਸ੍ਯਾਮ ਘਨੋ ਪੁਨਿ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Paithi tabai pratnaa ari kee madhi syaam ghano puni judhu machaayo |","meaning_en":"","page":508},{"gurmukhi":"ਸ੍ਰੀ ਬਲਬੀਰ ਸੁ ਧੀਰ ਗਹਿਯੋ ਰਿਪੁ ਕੋ ਸਬ ਹੀ ਦਲੁ ਮਾਰਿ ਭਗਾਯੋ। ੧੦੬੮।","roman":"Sree balbeer su dheer gahiyo ripu ko sab hee dalu maari bhagaayo | 1068 |","meaning_en":"","page":508}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":508},{"type":"verse","number":[1069],"number_text":"੧੦੬੯।","page":508,"lines":[{"gurmukhi":"ਭਗੀ ਚਮੂੰ ਚਤੁਰੰਗਨੀ ਨ੍ਰਿਪਤਿ ਨਿਹਾਰੀ ਨੈਨ।","roman":"Bhagee chamoon chaturangnee nripti nihaaree nain |","meaning_en":"","page":508},{"gurmukhi":"ਨਿਕਟਿ ਬਿਕਟਿ ਭਟ ਜੋ ਹੁਤੇ ਤਿਨ ਪ੍ਰਤਿ ਬੋਲਿਯੋ ਬੈਨ। ੧੦੬੯।","roman":"Nikti bikti bhat jo hute tin prati boliyo bain | 1069 |","meaning_en":"","page":508}]},{"type":"heading","kind":"speaker","name":"ਨ੍ਰਿਪ ਜਰਾਸੰਧਿ ਬਾਚ ਸੈਨਾ ਪ੍ਰਤਿ","gurmukhi":"ਨ੍ਰਿਪ ਜਰਾਸੰਧਿ ਬਾਚ ਸੈਨਾ ਪ੍ਰਤਿ","roman":"Nrip jaraasandhi baach sainaa prati","meaning_en":"","page":508},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":508},{"type":"verse","number":[1070],"number_text":"੧੦੭੦।","page":508,"lines":[{"gurmukhi":"ਜੁਧ ਕਰੈ ਘਨਿ ਸ੍ਯਾਮ ਜਹਾ ਤੁਮ ਹੂੰ ਦਲੁ ਲੈ ਉਨ ਓਰਿ ਸਿਧਾਰੋ।","roman":"Judh karai ghani syaam jahaa tum hoon dalu lai un ori sidhaaro |","meaning_en":"","page":508},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਕਰਿ ਲੈ ਜਦੁਬੀਰ ਕੋ ਦੇਹ ਪ੍ਰਹਾਰੋ।","roman":"Baan kamaan kripaan gadaa kari lai jadubeer ko deh prahaaro |","meaning_en":"","page":508},{"gurmukhi":"ਜਾਇ ਨ ਜੀਵਤ ਜਾਦਵ ਕੋ ਤਿਨ ਕੋ ਰਨ ਭੂਮਿ ਮੈ ਜਾਇ ਸੰਘਾਰੋ।","roman":"Jaai na jeevat jaadav ko tin ko ran bhoomi mai jaai sanghaaro |","meaning_en":"","page":508},{"gurmukhi":"ਯੌ ਜਬ ਬੈਨ ਕਹੈ ਨ੍ਰਿਪ ਸੈਨ ਚਲੀ ਚਤੁਰੰਗ ਜਹਾ ਰਨ ਭਾਰੋ। ੧੦੭੦।","roman":"Yau jab bain kahai nrip sain chalee chaturang jahaa ran bhaaro | 1070 |","meaning_en":"","page":508}]},{"type":"verse","number":[1071],"number_text":"੧੦੭੧।","page":508,"lines":[{"gurmukhi":"ਆਇਸ ਪਾਵਤ ਹੀ ਨ੍ਰਿਪ ਕੋ ਘਨ ਜਿਉ ਉਮਡੇ ਭਟ ਓਘ ਘਟਾ ਘਟ।","roman":"Aais paavat hee nrip ko ghan jiu umde bhat ogh ghataa ghat |","meaning_en":"","page":508},{"gurmukhi":"ਬਾਨਨ ਬੂੰਦਨ ਜਿਉ ਬਰਖੇ ਚਪਲਾ ਅਸਿ ਕੀ ਧੁਨਿ ਹੋਤ ਸਟਾ ਸਟ।","roman":"Baanan boondan jiu barkhe chaplaa asi kee dhuni hot sataa sat |","meaning_en":"","page":508},{"gurmukhi":"ਭੂਮਿ ਪਰੇ ਇਕ ਸਾਸ ਭਰੇ ਇਕ ਜੂਝਿ ਮਰੇ ਰਨਿ ਅੰਗ ਕਟਾ ਕਟ।","roman":"Bhoomi pare ik saas bhare ik joojhi mare rani ang kataa kat |","meaning_en":"","page":508},{"gurmukhi":"ਘਾਇਲ ਏਕ ਪਰੇ ਰਨ ਮੈ ਮੁਖ ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਰਟਾ ਰਟ। ੧੦੭੧।","roman":"Ghaail ek pare ran mai mukh maar hee maar pukaari rataa rat | 1071 |","meaning_en":"","page":508}]},{"type":"verse","number":[1072],"number_text":"੧੦੭੨।","page":509,"lines":[{"gurmukhi":"ਜਦੁਬੀਰ ਸਰਾਸਨ ਲੈ ਕਰਿ ਮੈ ਰਿਪੁ ਬੀਰ ਜਿਤੇ ਰਨ ਮਾਝਿ ਸੰਘਾਰੇ।","roman":"Jadubeer saraasan lai kari mai ripu beer jite ran maajhi sanghaare |","meaning_en":"","page":509},{"gurmukhi":"ਮਤਿ ਕਰੀ ਬਰ ਬਾਜ ਹਨੇ ਰਥ ਕਾਟਿ ਰਥੀ ਬਿਰਥੀ ਕਰਿ ਡਾਰੇ।","roman":"Mati karee bar baaj hane rath kaati rathee birthee kari daare |","meaning_en":"","page":509},{"gurmukhi":"ਘਾਇਲ ਦੇਖ ਕੈ ਕਾਇਰ ਜੇ ਡਰੁ ਮਾਨਿ ਰਨੇ ਛਿਤਿ ਤ੍ਯਾਗਿ ਸਿਧਾਰੇ।","roman":"Ghaail dekh kai kaair je daru maani rane chhiti tyaagi sidhaare |","meaning_en":"","page":509},{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਪੁੰਨ ਕੇ ਅਗ੍ਰਜ ਮਾਨਹੁ ਪਾਪਨ ਕੇ ਬਹੁ ਪੁੰਜ ਪਧਾਰੇ। ੧੦੭੨।","roman":"Sree hari punn ke agraj maanhu paapan ke bahu punj padhaare | 1072 |","meaning_en":"","page":509}]},{"type":"verse","number":[1073],"number_text":"੧੦੭੩।","page":509,"lines":[{"gurmukhi":"ਸੀਸ ਕਟੇ ਕਿਤਨੇ ਰਨ ਮੈ ਮੁਖ ਤੇ ਤੇਊ ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰੈ।","roman":"Sees kate kitne ran mai mukh te teoo maar hee maar pukaarai |","meaning_en":"","page":509},{"gurmukhi":"ਦਉਰਤ ਬੀਚ ਕਬੰਧ ਫਿਰੈ ਜਹ ਸ੍ਯਾਮ ਲਰੈ ਤਿਹ ਓਰਿ ਪਧਾਰੈ।","roman":"Daurat beech kabandh phirai jah syaam larai tih ori padhaarai |","meaning_en":"","page":509},{"gurmukhi":"ਜੋ ਭਟ ਆਇ ਭਿਰੈ ਇਨ ਸੋ ਤਿਨ ਕਉ ਹਰਿ ਜਾਨ ਕੈ ਘਾਇ ਪ੍ਰਹਾਰੈ।","roman":"Jo bhat aai bhirai in so tin kau hari jaan kai ghaai prahaarai |","meaning_en":"","page":509},{"gurmukhi":"ਜੋ ਗਿਰਿ ਭੂਮਿ ਪਰੈ ਮਰ ਕੈ ਕਰ ਤੇ ਕਰਵਾਰ ਨ ਭੂ ਪਰ ਡਾਰੈ। ੧੦੭੩।","roman":"Jo giri bhoomi parai mar kai kar te karvaar na bhoo par daarai | 1073 |","meaning_en":"","page":509}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":509},{"type":"verse","number":[1074],"number_text":"੧੦੭੪।","page":509,"lines":[{"gurmukhi":"ਕੋਪ ਅਤਿ ਭਰੇ ਰਨ ਭੂਮਿ ਤੇ ਨ ਟਰੇ","roman":"Kop ati bhare ran bhoomi te na tare","meaning_en":"","page":509},{"gurmukhi":"ਦੋਊ ਰੀਝਿ ਰੀਝਿ ਲਰੇ ਦਲ ਦੁੰਦਭੀ ਬਜਾਇ ਕੈ।","roman":"Do'oo reejhi reejhi lare dal dundbhee bajaai kai |","meaning_en":"","page":509},{"gurmukhi":"ਦੇਵ ਦੇਖੈ ਖਰੇ ਗਨ ਜਛ ਜਸੁ ਰਰੇ","roman":"Dev dekhai khare gan jachh jasu rare","meaning_en":"","page":509},{"gurmukhi":"ਨਭ ਤੇ ਪੁਹਪ ਢਰੇ ਮੇਘ ਬੂੰਦਨ ਜਿਉ ਆਇ ਕੈ।","roman":"Nabh te puhap dhare megh boondan jiu aai kai |","meaning_en":"","page":509},{"gurmukhi":"ਕੇਤੇ ਜੂਝਿ ਮਰੇ ਕੇਤੇ ਅਪਛਰਨ ਬਰੇ","roman":"Kete joojhi mare kete apachhran bare","meaning_en":"","page":509},{"gurmukhi":"ਕੇਤੇ ਗੀਧਨਨ ਚਰੇ ਕੇਤੇ ਗਿਰੇ ਘਾਇ ਖਾਇ ਕੈ।","roman":"Kete geedhnan chare kete gire ghaai khaai kai |","meaning_en":"","page":509},{"gurmukhi":"ਕੇਹਰਿ ਜਿਉ ਅਰੇ ਕੇਤੇ ਖੇਤ ਦੇਖਿ ਡਰੇ","roman":"Kehri jiu are kete khet dekhi dare","meaning_en":"","page":509},{"gurmukhi":"ਕੇਤੇ ਲਾਜ ਭਾਰਿ ਭਰੇ ਦਉਰਿ ਪਰੇ ਅਰਿਰਾਇ ਕੈ। ੧੦੭੪।","roman":"Kete laaj bhaari bhare dauri pare ariraai kai | 1074 |","meaning_en":"","page":509}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":509},{"type":"verse","number":[1075],"number_text":"੧੦੭੫।","page":509,"lines":[{"gurmukhi":"ਭੂਮਿ ਗਿਰੇ ਭਟ ਘਾਇਲ ਹੁਇ ਉਠ ਕੈ ਫਿਰਿ ਜੁਧ ਕੇ ਕਾਜ ਪਧਾਰੇ।","roman":"Bhoomi gire bhat ghaail hui uth kai phiri judh ke kaaj padhaare |","meaning_en":"","page":509},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹਾ ਦੁਰ ਕੈ ਜੁ ਰਹੇ ਅਤਿ ਕੋਪ ਭਰੇ ਇਹ ਭਾਤਿ ਪੁਕਾਰੇ।","roman":"Syaam kahaa dur kai ju rahe ati kop bhare ih bhaati pukaare |","meaning_en":"","page":509},{"gurmukhi":"ਯੌ ਉਨ ਕੈ ਮੁਖ ਤੇ ਸੁਨਿ ਬੈਨ ਭਯੋ ਹਰਿ ਸਾਮੁਹਿ ਖਗ ਸੰਭਾਰੇ।","roman":"Yau un kai mukh te suni bain bhayo hari saamuhi khag sanbhaare |","meaning_en":"","page":509},{"gurmukhi":"ਦਉਰ ਕੈ ਸੀਸ ਕਟੇ ਨ ਹਟੇ ਰਿਸ ਕੈ ਬਲਿਬੀਰ ਕੀ ਓਰਿ ਸਿਧਾਰੇ। ੧੦੭੫।","roman":"Daur kai sees kate na hate ris kai balibeer kee ori sidhaare | 1075 |","meaning_en":"","page":509}]},{"type":"verse","number":[1076],"number_text":"੧੦੭੬।","page":509,"lines":[{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰ ਤਬੈ ਰਨ ਮੈ ਅਸਿ ਲੈ ਲਲਕਾਰ ਪਰੇ।","roman":"Maar hee maar pukaar tabai ran mai asi lai lalkaar pare |","meaning_en":"","page":509},{"gurmukhi":"ਹਰਿ ਰਾਮ ਕੋ ਘੇਰਿ ਲਯੋ ਚਹੁੰ ਓਰ ਤੈ ਮਲਹਿ ਕੀ ਪਿਰ ਸੋਭ ਧਰੇ।","roman":"Hari raam ko gheri layo chahun or tai malhi kee pir sobh dhare |","meaning_en":"","page":509},{"gurmukhi":"ਧਨੁ ਬਾਨ ਜਬੈ ਕਰਿ ਸ੍ਯਾਮ ਲਯੋ ਲਖਿ ਕਾਤੁਰ ਖੇਤ ਹੂੰ ਤੇ ਬਿਡਰੇ।","roman":"Dhanu baan jabai kari syaam layo lakhi kaatur khet hoon te bidre |","meaning_en":"","page":509},{"gurmukhi":"ਰੰਗ ਭੂਮਿ ਕੋ ਮਾਨੋ ਉਝਾਰ ਭਯੋ ਚਲੇ ਕਉਤੁਕ ਦੇਖਨਹਾਰ ਘਰੇ। ੧੦੭੬।","roman":"Rang bhoomi ko maano ujhaar bhayo chale kautuk dekhanhaar ghare | 1076 |","meaning_en":"","page":509}]},{"type":"verse","number":[1077],"number_text":"੧੦੭੭।","page":510,"lines":[{"gurmukhi":"ਜੇ ਭਟ ਲੈ ਅਸਿ ਹਾਥਨ ਮੈ ਅਤਿ ਕੋਪ ਭਰੇ ਹਰਿ ਊਪਰ ਧਾਵੈ।","roman":"Je bhat lai asi haathan mai ati kop bhare hari oopar dhaavai |","meaning_en":"","page":510},{"gurmukhi":"ਕਉਤਕ ਸੋ ਦਿਖ ਕੈ ਸਿਵ ਕੇ ਗਨ ਆਨੰਦ ਸੋ ਮਿਲਿ ਮੰਗਲ ਗਾਵੈ।","roman":"Kautak so dikh kai siv ke gan aanand so mili mangal gaavai |","meaning_en":"","page":510},{"gurmukhi":"ਕੋਊ ਕਹੈ ਹਰਿਜੂ ਜਿਤ ਹੈ ਕੋਊ ਇਉ ਕਹਿ ਏ ਜਿਤ ਹੈ ਬਹਸਾਵੈ।","roman":"Ko'oo kahai harijoo jit hai ko'oo iu kahi e jit hai bahsaavai |","meaning_en":"","page":510},{"gurmukhi":"ਰਾਰਿ ਕਰੈ ਤਬ ਲਉ ਜਬ ਲਉ ਉਨ ਕਉ ਹਰਿ ਮਾਰਿ ਨ ਭੂਮਿ ਗਿਰਾਵੈ। ੧੦੭੭।","roman":"Raari karai tab lau jab lau un kau hari maari na bhoomi giraavai | 1077 |","meaning_en":"","page":510}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":510},{"type":"verse","number":[1078],"number_text":"੧੦੭੮।","page":510,"lines":[{"gurmukhi":"ਬਡੇ ਈ ਬਨੈਤ ਬੀਰ ਸਬੈ ਪਖਰੈਤ","roman":"Bade ee banait beer sabai pakhrait","meaning_en":"","page":510},{"gurmukhi":"ਗਜ ਦਲ ਸੋ ਅਰੈਤ ਧਾਏ ਤੁਰੰਗਨ ਨਚਾਇ ਕੈ।","roman":"Gaj dal so arait dhaae turangan nachaai kai |","meaning_en":"","page":510},{"gurmukhi":"ਜੁਧ ਮੈ ਅਡੋਲ ਸ੍ਵਾਮ ਕਾਰਜੀ ਅਮੋਲ ਅਤਿ","roman":"Judh mai adol svaam kaarjee amol ati","meaning_en":"","page":510},{"gurmukhi":"ਗੋਲ ਤੇ ਨਿਕਸਿ ਲਰੇ ਦੁੰਦਭਿ ਬਜਾਇ ਕੈ।","roman":"Gol te niksi lare dundbhi bajaai kai |","meaning_en":"","page":510},{"gurmukhi":"ਸੈਥਨ ਸੰਭਾਰ ਕੈ ਨਿਕਾਰ ਕੈ ਕ੍ਰਿਪਾਨ","roman":"Saithan sanbhaar kai nikaar kai kripaan","meaning_en":"","page":510},{"gurmukhi":"ਮਾਰ ਮਾਰ ਹੀ ਉਚਾਰਿ ਐਸੇ ਪਰੇ ਰਨਿ ਆਇ ਕੈ।","roman":"Maar maar hee uchaari aise pare rani aai kai |","meaning_en":"","page":510},{"gurmukhi":"ਹਰਿ ਜੂ ਸੋ ਲਰੇ ਤੇ ਵੈ ਠਉਰ ਤੇ ਨ ਟਰੇ","roman":"Hari joo so lare te vai thaur te na tare","meaning_en":"","page":510},{"gurmukhi":"ਗਿਰ ਭੂਮਿ ਹੂੰ ਮੈ ਪਰੇ ਉਠਿ ਅਰੇ ਘਾਇ ਖਾਇ ਕੈ। ੧੦੭੮।","roman":"Gir bhoomi hoon mai pare uthi are ghaai khaai kai | 1078 |","meaning_en":"","page":510}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":510},{"type":"verse","number":[1079],"number_text":"੧੦੭੯।","page":510,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਅਰਰਾਇ ਪਰੇ ਨ ਡਰੇ ਹਰਿ ਸਿਉ ਹਥਿਯਾਰ ਕਰੇ ਹੈ।","roman":"Kop bhare arraai pare na dare hari siu hathiyaar kare hai |","meaning_en":"","page":510},{"gurmukhi":"ਘਾਇ ਭਰੇ ਬਹੁ ਸ੍ਰਉਨ ਝਰੇ ਅਸਿ ਪਾਨਿ ਧਰੇ ਬਲ ਕੈ ਜੁ ਅਰੇ ਹੈ।","roman":"Ghaai bhare bahu sraun jhare asi paani dhare bal kai ju are hai |","meaning_en":"","page":510},{"gurmukhi":"ਮੂਸਲ ਲੈ ਬਲਦੇਵ ਤਬੈ ਸਬੈ ਚਾਵਰ ਜਿਉ ਰਨ ਮਾਹਿ ਛਰੇ ਹੈ।","roman":"Moosal lai baldev tabai sabai chaavar jiu ran maahi chhare hai |","meaning_en":"","page":510},{"gurmukhi":"ਫੇਰਿ ਪ੍ਰਹਾਰ ਕੀਯੋ ਹਲ ਸੋ ਮਰਿ ਭੂਮਿ ਗਿਰੇ ਨਹੀ ਸਾਸ ਭਰੇ ਹੈ। ੧੦੭੯।","roman":"Pheri prahaar keeyo hal so mari bhoomi gire nahee saas bhare hai | 1079 |","meaning_en":"","page":510}]},{"type":"verse","number":[1080],"number_text":"੧੦੮੦।","page":510,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੇ ਬੀਰ ਜਿਤੇ ਅਸਿ ਹਾਥਨ ਲੈ ਅਰਿ ਊਪਰਿ ਧਾਏ।","roman":"Sree jadubeer ke beer jite asi haathan lai ari oopri dhaae |","meaning_en":"","page":510},{"gurmukhi":"ਜੁਧ ਕਰਿਯੋ ਕਤਿ ਕੋਪੁ ਦੁਹੂੰ ਦਿਸਿ ਜੰਬੁਕ ਜੋਗਿਨ ਗ੍ਰਿਝ ਅਘਾਏ।","roman":"Judh kariyo kati kopu duhoon disi janbuk jogin grijh aghaae |","meaning_en":"","page":510},{"gurmukhi":"ਬੀਰ ਗਿਰੇ ਦੁਹੂੰ ਓਰਨ ਕੇ ਗਹਿ ਫੇਟ ਕਟਾਰਿਨ ਸਿਉ ਲਰਿ ਘਾਏ।","roman":"Beer gire duhoon oran ke gahi phet kataarin siu lari ghaae |","meaning_en":"","page":510},{"gurmukhi":"ਕਉਤਕ ਦੇਖ ਕੈ ਦੇਵ ਕਹੈ ਧੰਨ ਵੇ ਜਨਨੀ ਜਿਨ ਏ ਸੁਤ ਜਾਏ। ੧੦੮੦।","roman":"Kautak dekh kai dev kahai dhann ve jannee jin e sut jaae | 1080 |","meaning_en":"","page":510}]},{"type":"verse","number":[1081],"number_text":"੧੦੮੧।","page":510,"lines":[{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਬਰਬੀਰ ਹੁਤੇ ਅਤਿ ਰੋਸ ਭਰੇ ਰਨ ਭੂਮਹਿ ਆਏ।","roman":"Aur jite barbeer hute ati ros bhare ran bhoomhi aae |","meaning_en":"","page":510},{"gurmukhi":"ਜਾਦਵ ਸੈਨ ਚਲੀ ਇਤ ਤੇ ਤਿਨ ਹੂੰ ਮਿਲ ਕੈ ਅਤਿ ਜੁਧੁ ਮਚਾਏ।","roman":"Jaadav sain chalee it te tin hoon mil kai ati judhu machaae |","meaning_en":"","page":510},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਬਰਛੇ ਬਹੁ ਆਪਸ ਬੀਚ ਚਲਾਏ।","roman":"Baan kamaan kripaan gadaa barchhe bahu aapas beech chalaae |","meaning_en":"","page":510},{"gurmukhi":"ਭੇਦ ਚਮੂੰ ਜਦੁ ਬੀਰਨ ਕੀ ਸਭ ਹੀ ਜਦੁਰਾਇ ਕੇ ਊਪਰ ਧਾਏ। ੧੦੮੧।","roman":"Bhed chamoon jadu beeran kee sabh hee jaduraai ke oopar dhaae | 1081 |","meaning_en":"","page":510}]},{"type":"verse","number":[1082],"number_text":"੧੦੮੨।","page":510,"lines":[{"gurmukhi":"ਚਕ੍ਰ ਤ੍ਰਿਸੂਲ ਗਦਾ ਗਹਿ ਬੀਰ ਕਰੰ ਧਰ ਕੈ ਅਸਿ ਅਉਰ ਕਟਾਰੀ।","roman":"Chakr trisool gadaa gahi beer karan dhar kai asi aur kataaree |","meaning_en":"","page":510},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰੇ ਲਰੇ ਘਾਇ ਕਰੇ ਨ ਟਰੇ ਬਲ ਭਾਰੀ।","roman":"Maar hee maar pukaari pare lare ghaai kare na tare bal bhaaree |","meaning_en":"","page":510},{"gurmukhi":"ਸ੍ਯਾਮ ਬਿਦਾਰ ਦਈ ਧੁਜਨੀ ਤਿਹ ਕੀ ਉਪਮਾ ਇਹ ਭਾਤਿ ਬਿਚਾਰੀ।","roman":"Syaam bidaar daee dhujnee tih kee upmaa ih bhaati bichaaree |","meaning_en":"","page":511},{"gurmukhi":"ਮਾਨਹੁ ਖੇਤ ਸਰੋਵਰ ਮੈ ਧਸਿ ਕੈ ਗਜਿ ਬਾਰਜ ਬ੍ਯੂਹ ਬਿਡਾਰੀ। ੧੦੮੨।","roman":"Maanhu khet sarovar mai dhasi kai gaji baaraj byooh bidaaree | 1082 |","meaning_en":"","page":511}]},{"type":"verse","number":[1083],"number_text":"੧੦੮੩।","page":511,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਨਾਥ ਕੇ ਬਾਨਨ ਅਗ੍ਰ ਡਰੈ ਅਰਿ ਇਉ ਕਿਹੂੰ ਧੀਰ ਧਰਿਯੋ ਨਾ।","roman":"Sree jadunaath ke baanan agr darai ari iu kihoon dheer dhariyo naa |","meaning_en":"","page":511},{"gurmukhi":"ਬੀਰ ਸਬੈ ਹਟ ਕੇ ਠਟਕੇ ਭਟਕੇ ਰਨ ਭੀਤਰ ਜੁਧ ਕਰਿਯੋ ਨਾ।","roman":"Beer sabai hat ke thatke bhatke ran bheetar judh kariyo naa |","meaning_en":"","page":511},{"gurmukhi":"ਮੂਸਲ ਅਉ ਹਲ ਪਾਨਿ ਲਯੋ ਬਲਿ ਪੇਖਿ ਭਜੇ ਦਲ ਕੋਊ ਅਰਿਯੋ ਨਾ।","roman":"Moosal au hal paani layo bali pekhi bhaje dal ko'oo ariyo naa |","meaning_en":"","page":511},{"gurmukhi":"ਜਿਉ ਮ੍ਰਿਗ ਕੇ ਗਨ ਛਾਡਿ ਚਲੈ ਬਨ ਡੀਠ ਪਰਿਯੋ ਮ੍ਰਿਗਰਾਜ ਕੋ ਛਉਨਾ। ੧੦੮੩।","roman":"Jiu mrig ke gan chhaadi chalai ban deeth pariyo mrigraaj ko chhaunaa | 1083 |","meaning_en":"","page":511}]},{"type":"verse","number":[1084],"number_text":"੧੦੮੪।","page":511,"lines":[{"gurmukhi":"ਭਾਗਿ ਤਬੈ ਸਭ ਹੀ ਰਨ ਤੇ ਗਿਰਤੇ ਪਰਤੇ ਨ੍ਰਿਪ ਤੀਰ ਪੁਕਾਰੇ।","roman":"Bhaagi tabai sabh hee ran te girte parte nrip teer pukaare |","meaning_en":"","page":511},{"gurmukhi":"ਤੇਰੇ ਹੀ ਜੀਵਤ ਹੇ ਪ੍ਰਭੂ ਜੂ ਸਿਗਰੇ ਰਿਸ ਕੈ ਬਲ ਸ੍ਯਾਮ ਸੰਘਾਰੇ।","roman":"Tere hee jeevat he prabhoo joo sigre ris kai bal syaam sanghaare |","meaning_en":"","page":511},{"gurmukhi":"ਮਾਰੇ ਅਨੇਕ ਨ ਏਕ ਬਚਿਯੋ ਬਹੁ ਬੀਰ ਗਿਰੇ ਰਨਭੂਮਿ ਮਝਾਰੇ।","roman":"Maare anek na ek bachiyo bahu beer gire ranbhoomi majhaare |","meaning_en":"","page":511},{"gurmukhi":"ਤਾ ਤੇ ਸੁਨੋ ਬਿਨਤੀ ਹਮਰੀ ਉਨ ਜੀਤ ਭਈ ਤੁਮਰੇ ਦਲ ਹਾਰੇ। ੧੦੮੪।","roman":"Taa te suno bintee hamree un jeet bhaee tumre dal haare | 1084 |","meaning_en":"","page":511}]},{"type":"verse","number":[1085],"number_text":"੧੦੮੫।","page":511,"lines":[{"gurmukhi":"ਕੋਪ ਕਰਿਯੋ ਤਬ ਸੰਧਿ ਜਰਾ ਅਰਿ ਮਾਰਨ ਕਉ ਬਹੁ ਬੀਰ ਬੁਲਾਏ।","roman":"Kop kariyo tab sandhi jaraa ari maaran kau bahu beer bulaae |","meaning_en":"","page":511},{"gurmukhi":"ਆਇਸ ਪਾਵਤ ਹੀ ਨ੍ਰਿਪ ਕੈ ਮਿਲਿ ਕੈ ਹਰਿ ਕੇ ਬਧਬੇ ਕਹੁ ਧਾਏ।","roman":"Aais paavat hee nrip kai mili kai hari ke badhbe kahu dhaae |","meaning_en":"","page":511},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਗਦਾ ਗਹਿ ਕੈ ਉਮਡੇ ਘਨ ਜਿਉ ਘਨ ਸ੍ਯਾਮ ਪੈ ਆਏ।","roman":"Baan kamaan gadaa gahi kai umde ghan jiu ghan syaam pai aae |","meaning_en":"","page":511},{"gurmukhi":"ਆਇ ਪਰੇ ਹਰਿ ਊਪਰ ਸੋ ਮਿਲਿ ਕੈ ਬਗ ਮੇਲਿ ਤੁਰੰਗ ਉਠਾਏ। ੧੦੮੫।","roman":"Aai pare hari oopar so mili kai bag meli turang uthaae | 1085 |","meaning_en":"","page":511}]},{"type":"verse","number":[1086],"number_text":"੧੦੮੬।","page":511,"lines":[{"gurmukhi":"ਰੋਸ ਭਰੇ ਮਿਲਿ ਆਨਿ ਪਰੇ ਹਰਿ ਕਉ ਲਲਕਾਰ ਕੇ ਜੁਧ ਮਚਾਯੋ।","roman":"Ros bhare mili aani pare hari kau lalkaar ke judh machaayo |","meaning_en":"","page":511},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਯੌ ਤਿਨ ਸਾਰ ਸੋ ਸਾਰ ਬਜਾਯੋ।","roman":"Baan kamaan kripaan gadaa gahi yau tin saar so saar bajaayo |","meaning_en":"","page":511},{"gurmukhi":"ਘਾਇਲ ਆਪ ਭਏ ਭਟ ਸੋ ਅਰੁ ਸਸਤ੍ਰਨ ਸੋ ਹਰਿ ਕੋ ਤਨੁ ਘਾਯੋ।","roman":"Ghaail aap bhae bhat so aru sastran so hari ko tanu ghaayo |","meaning_en":"","page":511},{"gurmukhi":"ਦਉਰ ਪਰੇ ਹਲ ਮੂਸਲ ਲੈ ਬਲਿ ਬੈਰਨ ਕੋ ਦਲੁ ਮਾਰਿ ਗਿਰਾਯੋ। ੧੦੮੬।","roman":"Daur pare hal moosal lai bali bairan ko dalu maari giraayo | 1086 |","meaning_en":"","page":511}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":511},{"type":"verse","number":[1087],"number_text":"੧੦੮੭।","page":511,"lines":[{"gurmukhi":"ਜੂਝ ਪਰੈ ਜੇ ਨ੍ਰਿਪ ਬਲੀ ਹਰਿ ਸਿਉ ਜੁਧੁ ਮਚਾਇ।","roman":"Joojh parai je nrip balee hari siu judhu machaai |","meaning_en":"","page":511},{"gurmukhi":"ਤਿਨ ਬੀਰਨ ਕੇ ਨਾਮ ਸਬ ਸੋ ਕਬਿ ਕਹਤ ਸੁਨਾਇ। ੧੦੮੭।","roman":"Tin beeran ke naam sab so kabi kahat sunaai | 1087 |","meaning_en":"","page":511}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":511},{"type":"verse","number":[1088],"number_text":"੧੦੮੮।","page":511,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਨਰ ਸਿੰਘ ਬਲੀ ਗਜ ਸਿੰਘ ਚਲਿਯੋ ਧਨ ਸਿੰਘ ਸਰਾਸਨ ਲੈ।","roman":"Sree nar singh balee gaj singh chaliyo dhan singh saraasan lai |","meaning_en":"","page":511},{"gurmukhi":"ਹਰੀ ਸਿੰਘ ਬਡੋ ਰਨ ਸਿੰਘ ਨਰੇਸ ਤਹਾ ਕੋ ਚਲਿਯੋ ਦਿਜ ਕੋ ਧਨ ਦੈ।","roman":"Haree singh bado ran singh nares tahaa ko chaliyo dij ko dhan dai |","meaning_en":"","page":511},{"gurmukhi":"ਜਦੁਬੀਰ ਸੋ ਜਾਇ ਕੈ ਜੁਧ ਕਰਿਯੋ ਬਹੁਬੀਰ ਚਮੂੰ ਸੁ ਘਨੀ ਹਨਿ ਕੈ।","roman":"Jadubeer so jaai kai judh kariyo bahubeer chamoon su ghanee hani kai |","meaning_en":"","page":511},{"gurmukhi":"ਹਰਿ ਊਪਰਿ ਬਾਨ ਅਨੇਕ ਹਨੇ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਹਮਰੀ ਰਨਿ ਜੈ। ੧੦੮੮।","roman":"Hari oopri baan anek hane ih bhaati kahiyo hamree rani jai | 1088 |","meaning_en":"","page":511}]},{"type":"verse","number":[1089],"number_text":"੧੦੮੯।","page":512,"lines":[{"gurmukhi":"ਹੋਇ ਇਕਤ੍ਰ ਇਤੇ ਨ੍ਰਿਪ ਯੌ ਹਰਿ ਊਪਰ ਬਾਨ ਚਲਾਵਨ ਲਾਗੇ।","roman":"Hoi ikatr ite nrip yau hari oopar baan chalaavan laage |","meaning_en":"","page":512},{"gurmukhi":"ਕੋਪ ਕੈ ਜੁਧ ਕਰਿਯੋ ਤਿਨ ਹੂੰ ਬ੍ਰਿਜਨਾਇਕ ਤੇ ਪਗ ਦੁਇ ਕਰਿ ਆਗੇ।","roman":"Kop kai judh kariyo tin hoon brijnaaik te pag dui kari aage |","meaning_en":"","page":512},{"gurmukhi":"ਜੀਵ ਕੀ ਆਸ ਕਉ ਤ੍ਯਾਗਿ ਤਬੈ ਸਬ ਹੀ ਰਸ ਰੁਦ੍ਰ ਬਿਖੈ ਅਨੁਰਾਗੇ।","roman":"Jeev kee aas kau tyaagi tabai sab hee ras rudr bikhai anuraage |","meaning_en":"","page":512},{"gurmukhi":"ਚੀਰ ਧਰੇ ਸਿਤ ਆਏ ਹੁਤੇ ਛਿਨ ਬੀਚ ਭਏ ਸਭ ਆਰੁਨ ਬਾਗੇ। ੧੦੮੯।","roman":"Cheer dhare sit aae hute chhin beech bhae sabh aarun baage | 1089 |","meaning_en":"","page":512}]},{"type":"verse","number":[1090],"number_text":"੧੦੯੦।","page":512,"lines":[{"gurmukhi":"ਜੁਧ ਕਰਿਯੋ ਤਿਨ ਬੀਰਨ ਸ੍ਯਾਮ ਸੋ ਪਾਰਥ ਜ੍ਯੋ ਰਿਸ ਕੈ ਕਰਨੈ ਸੇ।","roman":"Judh kariyo tin beeran syaam so paarath jyo ris kai karnai se |","meaning_en":"","page":512},{"gurmukhi":"ਕੋਪ ਭਰਿਯੋ ਬਹੁ ਸੈਨ ਹਨੀ ਬਲਿਭਦ੍ਰ ਅਰਿਯੋ ਰਨ ਭੂ ਮਧਿ ਐਸੇ।","roman":"Kop bhariyo bahu sain hanee balibhadr ariyo ran bhoo madhi aise |","meaning_en":"","page":512},{"gurmukhi":"ਬੀਰ ਫਿਰੈ ਕਰਿ ਸਾਂਗਨਿ ਲੈ ਤਿਹ ਘੇਰਿ ਲਯੋ ਬਲਦੇਵਹਿ ਕੈਸੇ।","roman":"Beer phirai kari saangni lai tih gheri layo baldevhi kaise |","meaning_en":"","page":512},{"gurmukhi":"ਜੋਰਿ ਸੋ ਸਾਕਰਿ ਤੋਰਿ ਘਿਰਿਯੋ ਮਦਮਤ ਕਰੀ ਗਢਦਾਰਨ ਜੈਸੇ। ੧੦੯੦।","roman":"Jori so saakri tori ghiriyo madmat karee gadhdaaran jaise | 1090 |","meaning_en":"","page":512}]},{"type":"verse","number":[1091],"number_text":"੧੦੯੧।","page":512,"lines":[{"gurmukhi":"ਰਨਭੂਮਿ ਮੈ ਜੁਧ ਭਯੋ ਅਤਿ ਹੀ ਤਤਕਾਲ ਮਰੇ ਰਿਪੁ ਆਏ ਹੈ ਜੋਊ।","roman":"Ranbhoomi mai judh bhayo ati hee tatkaal mare ripu aae hai jo'oo |","meaning_en":"","page":512},{"gurmukhi":"ਜੁਧ ਕਰਿਯੋ ਘਨਿ ਸ੍ਯਾਮ ਘਨੋ ਉਤ ਕੋਪ ਭਰੇ ਮਨ ਮੈ ਭਟ ਓਊ।","roman":"Judh kariyo ghani syaam ghano ut kop bhare man mai bhat o'oo |","meaning_en":"","page":512},{"gurmukhi":"ਸ੍ਰੀ ਨਰਸਿੰਘ ਜੂ ਬਾਨ ਹਨ੍ਯੋ ਹਰਿ ਕੋ ਜਿਹ ਕੀ ਸਮ ਅਉਰ ਨ ਕੋਊ।","roman":"Sree narsingh joo baan hanyo hari ko jih kee sam aur na ko'oo |","meaning_en":"","page":512},{"gurmukhi":"ਯੌ ਉਪਮਾ ਉਪਜੀ ਜੀਯ ਮੈ ਜਿਵ ਸੋਵਤ ਸਿੰਘ ਜਗਾਵਤ ਕੋਊ। ੧੦੯੧।","roman":"Yau upmaa upjee jeey mai jiv sovat singh jagaavat ko'oo | 1091 |","meaning_en":"","page":512}]},{"type":"verse","number":[1092],"number_text":"੧੦੯੨।","page":512,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕੇ ਬਾਨ ਲਗਿਯੋ ਉਰ ਮੈ ਗਡ ਕੈ ਸੋਊ ਪੰਖਨ ਲਉ ਸੁ ਗਯੋ ਹੈ।","roman":"Syaam ke baan lagiyo ur mai gad kai so'oo pankhan lau su gayo hai |","meaning_en":"","page":512},{"gurmukhi":"ਸ੍ਰਉਨ ਕੇ ਸੰਗਿ ਭਰਿਯੋ ਸਰ ਅੰਗ ਬਿਲੋਕਿ ਤਬੈ ਹਰਿ ਕੋਪ ਭਯੋ ਹੈ।","roman":"Sraun ke sangi bhariyo sar ang biloki tabai hari kop bhayo hai |","meaning_en":"","page":512},{"gurmukhi":"ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਕਹਿ ਕੈ ਇਹ ਭਾਤ ਦਯੋ ਹੈ।","roman":"Taa chhabi ko jasu uch mahaa kabi ne kahi kai ih bhaat dayo hai |","meaning_en":"","page":512},{"gurmukhi":"ਮਾਨਹੁ ਤਛਕ ਕੋ ਲਰਿਕਾ ਖਗਰਾਜ ਲਖਿਯੋ ਗਹਿ ਨੀਲ ਲਯੋ ਹੈ। ੧੦੯੨।","roman":"Maanhu tachhak ko larikaa khagraaj lakhiyo gahi neel layo hai | 1092 |","meaning_en":"","page":512}]},{"type":"verse","number":[1093],"number_text":"੧੦੯੩।","page":512,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ ਸਰਾਸਨ ਲੈ ਰਿਸ ਕੈ ਸਰੁ ਰਾਜਨ ਬੀਚ ਕਸਾ।","roman":"Sree brijnaath saraasan lai ris kai saru raajan beech kasaa |","meaning_en":"","page":512},{"gurmukhi":"ਗਜ ਸਿੰਘ ਕੋ ਬਾਨ ਅਚਾਨ ਹਨ੍ਯੋ ਗਿਰ ਭੂਮਿ ਪਰਿਯੋ ਜਨ ਸਾਪ ਡਸਾ।","roman":"Gaj singh ko baan achaan hanyo gir bhoomi pariyo jan saap dasaa |","meaning_en":"","page":512},{"gurmukhi":"ਹਰਿ ਸਿੰਘ ਜੁ ਠਾਢੋ ਹੁਤੋ ਤਿਹ ਪੈ ਸੋਊ ਭਾਜ ਗਯੋ ਤਿਹ ਪੇਖਿ ਦਸਾ।","roman":"Hari singh ju thaadho huto tih pai so'oo bhaaj gayo tih pekhi dasaa |","meaning_en":"","page":512},{"gurmukhi":"ਮਨੋ ਸਿੰਘ ਕੋ ਰੂਪ ਨਿਹਾਰਤ ਹੀ ਨ ਟਿਕਿਯੋ ਜੁ ਚਲਿਯੋ ਸਟਕਾਇ ਸਸਾ। ੧੦੯੩।","roman":"Mano singh ko roop nihaarat hee na tikiyo ju chaliyo satkaai sasaa | 1093 |","meaning_en":"","page":512}]},{"type":"verse","number":[1094],"number_text":"੧੦੯੪।","page":512,"lines":[{"gurmukhi":"ਹਰਿ ਸਿੰਘ ਜਬੈ ਤਜਿ ਖੇਤ ਚਲਿਯੋ ਰਨ ਸਿੰਘ ਉਠਿਯੋ ਪੁਨਿ ਕੋਪ ਭਰਿਯੋ।","roman":"Hari singh jabai taji khet chaliyo ran singh uthiyo puni kop bhariyo |","meaning_en":"","page":512},{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰ ਕੈ ਪਾਨਿ ਲਯੋ ਬਹੁਰੋ ਬਲਿ ਕੋ ਰਨਿ ਜੁਧੁ ਕਰਿਯੋ।","roman":"Dhanu baan sanbhaar kai paani layo bahuro bali ko rani judhu kariyo |","meaning_en":"","page":512},{"gurmukhi":"ਉਨ ਹੂੰ ਪੁਨਿ ਬੀਚ ਅਯੋਧਨ ਕੇ ਹਰਿ ਕੋ ਲਲਕਾਰ ਕੈ ਇਉ ਉਚਰਿਯੋ।","roman":"Un hoon puni beech ayodhan ke hari ko lalkaar kai iu uchriyo |","meaning_en":"","page":512},{"gurmukhi":"ਅਬ ਜਾਤ ਕਹਾ ਥਿਰੁ ਹੋਹੁ ਘਰੀ ਹਮਰੇ ਅਸਿ ਕਾਲ ਕੇ ਹਾਥ ਪਰਿਯੋ। ੧੦੯੪।","roman":"Ab jaat kahaa thiru hohu gharee hamre asi kaal ke haath pariyo | 1094 |","meaning_en":"","page":512}]},{"type":"verse","number":[1095],"number_text":"੧੦੯੫।","page":513,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਰਨ ਸਿੰਘ ਜਬੈ ਹਰਿ ਸਿੰਘ ਤਬੈ ਸੁਨਿ ਕੈ ਮੁਸਕਾਨ੍ਯੋ।","roman":"Ih bhaati kahiyo ran singh jabai hari singh tabai suni kai muskaanyo |","meaning_en":"","page":513},{"gurmukhi":"ਆਇ ਅਰਿਯੋ ਹਰਿ ਸਿਉ ਧਨੁ ਲੈ ਰਨ ਕੀ ਛਿਤ ਤੇ ਨਹੀ ਪੈਗ ਪਰਾਨ੍ਯੋ।","roman":"Aai ariyo hari siu dhanu lai ran kee chhit te nahee paig paraanyo |","meaning_en":"","page":513},{"gurmukhi":"ਕੋਪ ਕੈ ਬਾਤ ਕਹੀ ਜਦੁਬੀਰ ਸੋ ਮੈ ਇਹ ਲਛਨ ਤੇ ਪਹਚਾਨ੍ਯੋ।","roman":"Kop kai baat kahee jadubeer so mai ih lachhan te pahchaanyo |","meaning_en":"","page":513},{"gurmukhi":"ਆਇ ਕੈ ਜੁਧ ਕੀਓ ਹਮ ਸੋ ਸੁ ਭਲੀ ਬਿਧਿ ਕਾਲ ਕੇ ਹਾਥ ਬਿਕਾਨ੍ਯੋ। ੧੦੯੫।","roman":"Aai kai judh keeo ham so su bhalee bidhi kaal ke haath bikaanyo | 1095 |","meaning_en":"","page":513}]},{"type":"verse","number":[1096],"number_text":"੧੦੯੬।","page":513,"lines":[{"gurmukhi":"ਯੌ ਸੁਨ ਕੈ ਬਤੀਆ ਤਿਹ ਕੀ ਹਰਿ ਜੂ ਧਨੁ ਲੈ ਕਰ ਮੈ ਮੁਸਕ੍ਯੋ ਹੈ।","roman":"Yau sun kai bateeaa tih kee hari joo dhanu lai kar mai muskyo hai |","meaning_en":"","page":513},{"gurmukhi":"ਦੀਰਘੁ ਗਾਤ ਲਖਿਯੋ ਤਬ ਹੀ ਸਰ ਛਾਡਿ ਦਯੋ ਅਰ ਸੀਸ ਤਕ੍ਯੋ ਹੈ।","roman":"Deerghu gaat lakhiyo tab hee sar chhaadi dayo ar sees takyo hai |","meaning_en":"","page":513},{"gurmukhi":"ਬਾਨ ਲਗਿਯੋ ਹਰਿ ਸਿੰਘ ਤਬੈ ਸਿਰ ਟੂਟਿ ਪਰਿਯੋ ਧਰ ਠਾਢੋ ਰਹਿਯੋ ਹੈ।","roman":"Baan lagiyo hari singh tabai sir tooti pariyo dhar thaadho rahiyo hai |","meaning_en":"","page":513},{"gurmukhi":"ਮੇਰੁ ਕੇ ਸ੍ਰਿੰਗਹੁ ਤੇ ਉਤਰਿਯੋ ਸੁ ਮਨੋ ਰਵਿ ਅਸਤ ਕੋ ਪ੍ਰਾਤਿ ਭਯੋ ਹੈ। ੧੦੯੬।","roman":"Meru ke sringhu te utriyo su mano ravi asat ko praati bhayo hai | 1096 |","meaning_en":"","page":513,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"verse","number":[1097],"number_text":"੧੦੯੭।","page":513,"lines":[{"gurmukhi":"ਮਾਰ ਲਯੋ ਹਰਿ ਸਿੰਘ ਜਬੈ ਰਨ ਸਿੰਘ ਤਬੈ ਹਰਿ ਊਪਰਿ ਧਾਯੋ।","roman":"Maar layo hari singh jabai ran singh tabai hari oopri dhaayo |","meaning_en":"","page":513},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਕੈ ਕਰ ਮੈ ਅਤਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Baan kamaan kripaan gadaa gahi kai kar mai ati judh machaayo |","meaning_en":"","page":513},{"gurmukhi":"ਕੌਚ ਸਜੇ ਨਿਜ ਅੰਗ ਮਹਾ ਲਖਿ ਕੈ ਕਬਿ ਨੇ ਇਹ ਬਾਤ ਸੁਨਾਯੋ।","roman":"Kauch saje nij ang mahaa lakhi kai kabi ne ih baat sunaayo |","meaning_en":"","page":513},{"gurmukhi":"ਮਾਨਹੁ ਮਤ ਕਰੀ ਬਨ ਮੈ ਰਿਸ ਕੈ ਮ੍ਰਿਗਰਾਜ ਕੇ ਊਪਰ ਆਯੋ। ੧੦੯੭।","roman":"Maanhu mat karee ban mai ris kai mrigraaj ke oopar aayo | 1097 |","meaning_en":"","page":513}]},{"type":"verse","number":[1098],"number_text":"੧੦੯੮।","page":513,"lines":[{"gurmukhi":"ਆਇ ਕੇ ਸ੍ਯਾਮ ਸੋ ਜੁਧੁ ਕਰਿਯੋ ਰਨ ਕੀ ਛਿਤਿ ਤੇ ਪਗੁ ਏਕ ਨ ਭਾਗਿਯੋ।","roman":"Aai ke syaam so judhu kariyo ran kee chhiti te pagu ek na bhaagiyo |","meaning_en":"","page":513},{"gurmukhi":"ਫੇਰਿ ਗਦਾ ਗਹਿ ਕੈ ਕਰ ਮੈ ਬ੍ਰਿਜਭੂਖਨ ਕੋ ਤਨੁ ਤਾੜਨ ਲਾਗਿਯੋ।","roman":"Pheri gadaa gahi kai kar mai brijbhookhan ko tanu taaran laagiyo |","meaning_en":"","page":513},{"gurmukhi":"ਸੋ ਮਧਸੂਦਨ ਜੂ ਲਖਿਯੋ ਰਸ ਰੁਦ੍ਰ ਬਿਖੈ ਅਤਿ ਇਹ ਪਾਗਿਯੋ।","roman":"So madhsoodan joo lakhiyo ras rudr bikhai ati ih paagiyo |","meaning_en":"","page":513},{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਚਕ੍ਰ ਲਯੋ ਕਰ ਮੈ ਭੂਅ ਬਕ੍ਰ ਕਰੀ ਰਿਸ ਸੋ ਅਨੁਰਾਗਿਯੋ। ੧੦੯੮।","roman":"Sree hari chakr layo kar mai bhooa bakr karee ris so anuraagiyo | 1098 |","meaning_en":"","page":513}]},{"type":"verse","number":[1099],"number_text":"੧੦੯੯।","page":513,"lines":[{"gurmukhi":"ਲੈ ਬਰਛੀ ਰਨ ਸਿੰਘ ਤਬੈ ਜਦੁਬੀਰ ਕੇ ਮਾਰਨ ਕਾਜ ਚਲਾਈ।","roman":"Lai barchhee ran singh tabai jadubeer ke maaran kaaj chalaaee |","meaning_en":"","page":513},{"gurmukhi":"ਜਾਇ ਲਗੀ ਹਰਿ ਕੋ ਅਨਚੇਤ ਦਈ ਭੁਜ ਫੋਰ ਕੈ ਪਾਰਿ ਦਿਖਾਈ।","roman":"Jaai lagee hari ko anchet daee bhuj phor kai paari dikhaaee |","meaning_en":"","page":513},{"gurmukhi":"ਲਾਗ ਰਹੀ ਪ੍ਰਭ ਕੇ ਤਨ ਸਿਉ ਉਪਮਾ ਤਿਹ ਕੀ ਕਬਿ ਭਾਖਿ ਸੁਨਾਈ।","roman":"Laag rahee prabh ke tan siu upmaa tih kee kabi bhaakhi sunaaee |","meaning_en":"","page":513},{"gurmukhi":"ਮਾਨਹੁ ਗ੍ਰੀਖਮ ਕੀ ਰੁਤਿ ਭੀਤਰ ਨਾਗਨਿ ਚੰਦਨ ਸਿਉ ਲਪਟਾਈ। ੧੦੯੯।","roman":"Maanhu greekham kee ruti bheetar naagni chandan siu laptaaee | 1099 |","meaning_en":"","page":513}]},{"type":"verse","number":[1100],"number_text":"੧੧੦੦।","page":513,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਉਖਾਰ ਕੈ ਸੋ ਬਰਛੀ ਭੁਜ ਤੇ ਅਰਿ ਮਾਰਨ ਹੇਤ ਚਲਾਈ।","roman":"Syaam ukhaar kai so barchhee bhuj te ari maaran het chalaaee |","meaning_en":"","page":513},{"gurmukhi":"ਬਾਨਨ ਕੇ ਘਨ ਬੀਚ ਚਲੀ ਚਪਲਾ ਕਿਧੌ ਹੰਸ ਕੀ ਅੰਸ ਤਚਾਈ।","roman":"Baanan ke ghan beech chalee chaplaa kidhau hans kee ans tachaaee |","meaning_en":"","page":513},{"gurmukhi":"ਜਾਇ ਲਗੀ ਤਿਹ ਕੇ ਤਨ ਮੈ ਉਰਿ ਫੋਰਿ ਦਈ ਉਹਿ ਓਰ ਦਿਖਾਈ।","roman":"Jaai lagee tih ke tan mai uri phori daee uhi or dikhaaee |","meaning_en":"","page":513},{"gurmukhi":"ਕਾਲਿਕਾ ਮਾਨਹੁ ਸ੍ਰਉਨ ਭਰੀ ਹਨਿ ਸੁੰਭ ਨਿਸੁੰਭ ਕੋ ਮਾਰਨ ਧਾਈ। ੧੧੦੦।","roman":"Kaalikaa maanhu sraun bharee hani sunbh nisunbh ko maaran dhaaee | 1100 |","meaning_en":"","page":513}]},{"type":"verse","number":[1101],"number_text":"੧੧੦੧।","page":513,"lines":[{"gurmukhi":"ਰਨ ਸਿੰਘ ਜਬੈ ਰਣਿ ਸਾਂਗ ਹਨ੍ਯੋ ਧਨ ਸਿੰਘ ਤਬੈ ਕਰਿ ਕੋਪੁ ਸਿਧਾਰਿਯੋ।","roman":"Ran singh jabai rani saang hanyo dhan singh tabai kari kopu sidhaariyo |","meaning_en":"","page":513},{"gurmukhi":"ਧਾਇ ਪਰਿਯੋ ਕਰਿ ਲੈ ਬਰਛਾ ਲਲਕਾਰ ਕੈ ਸ੍ਰੀ ਹਰਿ ਊਪਰਿ ਝਾਰਿਯੋ।","roman":"Dhaai pariyo kari lai barchhaa lalkaar kai sree hari oopri jhaariyo |","meaning_en":"","page":513},{"gurmukhi":"ਆਵਤ ਸੋ ਲਖਿਯੋ ਘਨ ਸ੍ਯਾਮ ਨਿਕਾਰ ਕੈ ਖਗ ਸੁ ਦੁਇ ਕਰਿ ਡਾਰਿਯੋ।","roman":"Aavat so lakhiyo ghan syaam nikaar kai khag su dui kari daariyo |","meaning_en":"","page":513},{"gurmukhi":"ਭੂਮਿ ਦੁਟੂਕ ਹੋਇ ਟੂਟ ਪਰਿਯੋ ਸੁ ਮਨੋ ਖਗਰਾਜ ਬਡੋ ਅਹਿ ਮਾਰਿਯੋ। ੧੧੦੧।","roman":"Bhoomi dutook hoi toot pariyo su mano khagraaj bado ahi maariyo | 1101 |","meaning_en":"","page":513}]},{"type":"verse","number":[1102],"number_text":"੧੧੦੨।","page":514,"lines":[{"gurmukhi":"ਘਾਉ ਬਚਾਇ ਕੈ ਸ੍ਰੀ ਜਦੁਬੀਰ ਸਰਾਸਨੁ ਲੈ ਅਰਿ ਊਪਰਿ ਧਾਯੋ।","roman":"Ghaau bachaai kai sree jadubeer saraasnu lai ari oopri dhaayo |","meaning_en":"","page":514},{"gurmukhi":"ਚਾਰ ਮਹੂਰਤ ਜੁਧ ਭਯੋ ਹਰਿ ਘਾਇ ਨ ਹੁਇ ਉਹਿ ਕੋ ਨਹੀ ਘਾਯੋ।","roman":"Chaar mahoorat judh bhayo hari ghaai na hui uhi ko nahee ghaayo |","meaning_en":"","page":514},{"gurmukhi":"ਰੋਸ ਕੈ ਬਾਨ ਹਨ੍ਯੋ ਹਰਿ ਕਉ ਹਰਿ ਹੂੰ ਤਿਹ ਖੈਚ ਕੈ ਬਾਨ ਲਗਾਯੋ।","roman":"Ros kai baan hanyo hari kau hari hoon tih khaich kai baan lagaayo |","meaning_en":"","page":514},{"gurmukhi":"ਦੇਖ ਰਹਿਯੋ ਮੁਖ ਸ੍ਰੀ ਹਰਿ ਕੋ ਹਰਿ ਹੂੰ ਮੁਖ ਦੇਖ ਰਹਿਯੋ ਮੁਸਕਾਯੋ। ੧੧੦੨।","roman":"Dekh rahiyo mukh sree hari ko hari hoon mukh dekh rahiyo muskaayo | 1102 |","meaning_en":"","page":514}]},{"type":"verse","number":[1103],"number_text":"੧੧੦੩।","page":514,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੋ ਬੀਰ ਬਲੀ ਅਸਿ ਲੈ ਕਰ ਮੈ ਧਨਸਿੰਘ ਪੈ ਧਾਯੋ।","roman":"Sree jadubeer ko beer balee asi lai kar mai dhansingh pai dhaayo |","meaning_en":"","page":514},{"gurmukhi":"ਆਵਤ ਹੀ ਲਲਕਾਰ ਪਰਿਯੋ ਗਜਿ ਮਾਨਹੁ ਕੇਹਰਿ ਕਉ ਡਰਪਾਯੋ।","roman":"Aavat hee lalkaar pariyo gaji maanhu kehri kau darpaayo |","meaning_en":"","page":514},{"gurmukhi":"ਤਉ ਧਨ ਸਿੰਘ ਸਰਾਸਨੁ ਲੈ ਸਰ ਸੋ ਤਿਹ ਕੋ ਸਿਰ ਭੂਮਿ ਗਿਰਾਯੋ।","roman":"Tau dhan singh saraasnu lai sar so tih ko sir bhoomi giraayo |","meaning_en":"","page":514},{"gurmukhi":"ਜਿਉ ਅਹਿ ਰਾਜ ਕੇ ਆਨਨ ਭੀਤਰ ਆਨਿ ਪਰਿਯੋ ਮ੍ਰਿਗ ਜਾਨ ਨ ਪਾਯੋ। ੧੧੦੩।","roman":"Jiu ahi raaj ke aanan bheetar aani pariyo mrig jaan na paayo | 1103 |","meaning_en":"","page":514}]},{"type":"verse","number":[1104],"number_text":"੧੧੦੪।","page":514,"lines":[{"gurmukhi":"ਦੂਸਰ ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੇ ਬੀਰ ਸਰਾਸਨੁ ਲੈ ਸਰ ਕੋਪ ਭਯੋ ਹੈ।","roman":"Doosar sree jadubeer ke beer saraasnu lai sar kop bhayo hai |","meaning_en":"","page":514},{"gurmukhi":"ਧੀਰ ਬਲੀ ਧਨ ਸਿੰਘ ਕੀ ਓਰ ਚਲਾਵਤ ਬਾਨ ਨਿਸੰਕ ਗਯੋ ਹੈ।","roman":"Dheer balee dhan singh kee or chalaavat baan nisank gayo hai |","meaning_en":"","page":514},{"gurmukhi":"ਸ੍ਰੀ ਧਨ ਸਿੰਘ ਲੀਓ ਅਸਿ ਹਾਥਿ ਕਟਿਓ ਅਰਿ ਮਾਥਨ ਡਾਰ ਦਯੋ ਹੈ।","roman":"Sree dhan singh leeo asi haathi katio ari maathan daar dayo hai |","meaning_en":"","page":514},{"gurmukhi":"ਕਾਛੀ ਨਿਹਾਰਿ ਸਰੋਵਰ ਤੇ ਪ੍ਰਫੁਲਿਓ ਮਾਨਹੁ ਬਾਰਿਜ ਤੋਰ ਲਯੋ ਹੈ। ੧੧੦੪।","roman":"Kaachhee nihaari sarovar te praphulio maanhu baarij tor layo hai | 1104 |","meaning_en":"","page":514}]},{"type":"verse","number":[1105],"number_text":"੧੧੦੫।","page":514,"lines":[{"gurmukhi":"ਮਾਰਿ ਦੁ ਬੀਰਨ ਕੋ ਧਨ ਸਿੰਘ ਸਰਾਸਨ ਲੈ ਦਲ ਕਉ ਤਕਿ ਧਾਯੋ।","roman":"Maari du beeran ko dhan singh saraasan lai dal kau taki dhaayo |","meaning_en":"","page":514},{"gurmukhi":"ਆਵਤ ਹੀ ਗਜਿ ਬਾਜ ਹਨੇ ਰਥ ਪੈਦਲ ਕਾਟਿ ਘਨੋ ਰਨ ਪਾਯੋ।","roman":"Aavat hee gaji baaj hane rath paidal kaati ghano ran paayo |","meaning_en":"","page":514},{"gurmukhi":"ਖਗ ਅਲਾਤ ਕੀ ਭਾਤਿ ਫਿਰਿਓ ਖਰ ਸਾਨ ਨ੍ਰਿਪਾਲ ਕੋ ਛਤ੍ਰ ਲਜਾਯੋ।","roman":"Khag alaat kee bhaati phirio khar saan nripaal ko chhatr lajaayo |","meaning_en":"","page":514},{"gurmukhi":"ਅਉਰ ਭਲੀ ਉਪਮਾ ਤਿਹ ਕੀ ਲਖਿ ਭੀਖਮ ਕਉ ਹਰਿ ਚਕ੍ਰ ਭ੍ਰਮਾਯੋ। ੧੧੦੫।","roman":"Aur bhalee upmaa tih kee lakhi bheekham kau hari chakr bhramaayo | 1105 |","meaning_en":"","page":514}]},{"type":"verse","number":[1106],"number_text":"੧੧੦੬।","page":514,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਧਨ ਸਿੰਘ ਸਰਾਸਨੁ ਲੈ ਰਿਸ ਕੈ ਅਰਿ ਕੇ ਦਲ ਮਾਝਿ ਪਰਿਯੋ।","roman":"Bahuro dhan singh saraasnu lai ris kai ari ke dal maajhi pariyo |","meaning_en":"","page":514},{"gurmukhi":"ਰਥਿ ਕਾਟਿ ਘਨੇ ਗਜ ਬਾਜ ਹਨੇ ਨਹੀ ਜਾਤ ਗਨੇ ਇਹ ਭਾਤਿ ਲਰਿਯੋ।","roman":"Rathi kaati ghane gaj baaj hane nahee jaat gane ih bhaati lariyo |","meaning_en":"","page":514},{"gurmukhi":"ਜਮਲੋਕੁ ਸੁ ਬੀਰ ਕਿਤੇ ਪਠਏ ਹਰਿ ਓਰ ਚਲਿਯੋ ਅਤਿ ਕੋਪ ਭਰਿਯੋ।","roman":"Jamloku su beer kite pathae hari or chaliyo ati kop bhariyo |","meaning_en":"","page":514},{"gurmukhi":"ਮੁਖ ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰਿਯੋ ਦਲੁ ਜਾਦਵ ਕੋ ਸਿਗਰੋ ਬਿਡਰਿਯੋ। ੧੧੦੬।","roman":"Mukh maar hee maar pukaari pariyo dalu jaadav ko sigro bidriyo | 1106 |","meaning_en":"","page":514}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":514},{"type":"verse","number":[1107],"number_text":"੧੧੦੭।","page":514,"lines":[{"gurmukhi":"ਧਨ ਸਿੰਘ ਸੈਨਾ ਜਾਦਵੀ ਦੀਨੀ ਘਨੀ ਖਪਾਇ।","roman":"Dhan singh sainaa jaadvee deenee ghanee khapaai |","meaning_en":"","page":514},{"gurmukhi":"ਤਬ ਬ੍ਰਿਜ ਭੂਖਨ ਕੋਪਿ ਭਰਿ ਬੋਲਿਯੋ ਨੈਨ ਤਚਾਇ। ੧੧੦੭।","roman":"Tab brij bhookhan kopi bhari boliyo nain tachaai | 1107 |","meaning_en":"","page":514}]},{"type":"heading","kind":"speaker","name":"ਕਾਨੁ ਬਾਚ ਸੈਨਾ ਪ੍ਰਤਿ","gurmukhi":"ਕਾਨੁ ਬਾਚ ਸੈਨਾ ਪ੍ਰਤਿ","roman":"Kaanu baach sainaa prati","meaning_en":"","page":514},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":514},{"type":"verse","number":[1108],"number_text":"੧੧੦੮।","page":514,"lines":[{"gurmukhi":"ਦੇਖਤ ਹੋ ਭਟ ਠਾਢੇ ਕਹਾ ਹਮ ਜਾਨਤ ਹੈ ਤੁਮ ਪਉਰਖ ਹਾਰਿਯੋ।","roman":"Dekhat ho bhat thaadhe kahaa ham jaanat hai tum paurakh haariyo |","meaning_en":"","page":514},{"gurmukhi":"ਸ੍ਰੀ ਧਨ ਸਿੰਘ ਕੇ ਬਾਨ ਛੁਟੇ ਸਭ ਹੂੰ ਰਨ ਮੰਡਲ ਤੇ ਪਗ ਟਾਰਿਯੋ।","roman":"Sree dhan singh ke baan chhute sabh hoon ran mandal te pag taariyo |","meaning_en":"","page":514},{"gurmukhi":"ਸਿੰਘ ਕੇ ਅਗ੍ਰਜ ਜੈਸੇ ਅਜਾ ਗਨ ਐਸੇ ਭਜੇ ਨਹਿ ਸਸਤ੍ਰ ਸੰਭਾਰਿਯੋ।","roman":"Singh ke agraj jaise ajaa gan aise bhaje nahi sasatr sanbhaariyo |","meaning_en":"","page":515},{"gurmukhi":"ਕਾਇਰ ਹੁਇ ਤਿਹ ਪੇਖਿ ਡਰੇ ਨਹਿ ਆਪ ਮਰੇ ਉਨ ਕਉ ਨਹੀ ਮਾਰਿਯੋ। ੧੧੦੮।","roman":"Kaair hui tih pekhi dare nahi aap mare un kau nahee maariyo | 1108 |","meaning_en":"","page":515}]},{"type":"verse","number":[1109],"number_text":"੧੧੦੯।","page":515,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਹਰਿ ਕੀ ਬਤੀਯਾ ਭਟ ਦਾਤਨ ਪੀਸ ਕੈ ਕ੍ਰੋਧ ਭਰੇ।","roman":"Yau suni kai hari kee bateeyaa bhat daatan pees kai krodh bhare |","meaning_en":"","page":515},{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰ ਕੈ ਧਾਇ ਪਰੇ ਧਨ ਸਿੰਘਹੁੰ ਤੇ ਨਹੀ ਨੈਕੁ ਡਰੇ।","roman":"Dhanu baan sanbhaar kai dhaai pare dhan singhhun te nahee naiku dare |","meaning_en":"","page":515},{"gurmukhi":"ਧਨ ਸਿੰਘ ਸਰਾਸਨੁ ਲੈ ਕਰਿ ਮੈ ਕਟਿ ਦੈਤਨ ਕੇ ਸਿਰ ਭੂਮਿ ਪਰੇ।","roman":"Dhan singh saraasnu lai kari mai kati daitan ke sir bhoomi pare |","meaning_en":"","page":515},{"gurmukhi":"ਮਨੋ ਪਉਨ ਕੋ ਪੁੰਜ ਬਹਿਯੋ ਲਗ ਕੇ ਫੁਲਵਾਰੀ ਮੈ ਟੂਟ ਕੈ ਫੂਲਿ ਝਰੈ। ੧੧੦੯।","roman":"Mano paun ko punj bahiyo lag ke phulvaaree mai toot kai phooli jharai | 1109 |","meaning_en":"","page":515}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":515},{"type":"verse","number":[1110],"number_text":"੧੧੧੦।","page":515,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਆਏ ਭਟ ਗਿਰੇ ਰਨਿ ਭੂਮਿ ਕਟਿ","roman":"Kop bhare aae bhat gire rani bhoomi kati","meaning_en":"","page":515},{"gurmukhi":"ਜੁਧ ਕੇ ਨਿਪਟ ਸਮੁਹਾਇ ਸਿੰਘ ਧਨ ਸੋ।","roman":"Judh ke nipat samuhaai singh dhan so |","meaning_en":"","page":515},{"gurmukhi":"ਆਯੁਧ ਲੈ ਪਾਨ ਮੈ ਨਿਦਾਨ ਕੋ ਸਮਰ ਜਾਨਿ","roman":"Aayudh lai paan mai nidaan ko samar jaani","meaning_en":"","page":515},{"gurmukhi":"ਅਉਰ ਦਉਰ ਪਰੇ ਬੀਰਤਾ ਬਢਾਇ ਮਨ ਸੋ।","roman":"Aur daur pare beertaa badhaai man so |","meaning_en":"","page":515},{"gurmukhi":"ਕੋਪ ਧਨ ਸਿੰਘ ਲੈ ਸਰਾਸਨ ਸੁ ਬਾਨ ਤਾਨਿ","roman":"Kop dhan singh lai saraasan su baan taani","meaning_en":"","page":515},{"gurmukhi":"ਜੁਦੇ ਕਰ ਡਾਰੇ ਸੀਸ ਤਿਨ ਹੀ ਕੇ ਤਨ ਸੋ।","roman":"Jude kar daare sees tin hee ke tan so |","meaning_en":"","page":515},{"gurmukhi":"ਮਾਨਹੁ ਬਸੁੰਧਰਾ ਕੀ ਧੀਰਤਾ ਨਿਹਾਰ ਇੰਦ੍ਰ","roman":"Maanhu basundhraa kee dheertaa nihaar indr","meaning_en":"","page":515},{"gurmukhi":"ਕੀਨੀ ਨਿਜ ਪੂਜਾ ਅਰਬਿੰਦ ਪੁਹਪਨ ਸੋ। ੧੧੧੦।","roman":"Keenee nij poojaa arbind puhpan so | 1110 |","meaning_en":"","page":515}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":515},{"type":"verse","number":[1111],"number_text":"੧੧੧੧।","page":515,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਧਨ ਸਿੰਘ ਅਯੋਧਨ ਮੈ ਅਤਿ ਕੋਪ ਕੀਯੋ ਬਹੁਤੇ ਭਟ ਮਾਰੇ।","roman":"Sree dhan singh ayodhan mai ati kop keeyo bahute bhat maare |","meaning_en":"","page":515},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਬਰ ਆਵਤ ਹੇ ਸੁ ਹਨੇ ਜਨੁ ਮਾਰੁਤ ਮੇਘ ਬਿਡਾਰੇ।","roman":"Aur jite bar aavat he su hane janu maarut megh bidaare |","meaning_en":"","page":515},{"gurmukhi":"ਜਾਦਵ ਕੇ ਦਲ ਕੇ ਗਜ ਕੇ ਹਲਕੇ ਦਲ ਕੇ ਹਲਕੇ ਕਰਿ ਡਾਰੇ।","roman":"Jaadav ke dal ke gaj ke halke dal ke halke kari daare |","meaning_en":"","page":515},{"gurmukhi":"ਝੂਮਿ ਗਿਰੇ ਇਕ ਯੌ ਧਰਨੀ ਮਨੋ ਇੰਦ੍ਰ ਕੇ ਬਜ੍ਰ ਲਗੇ ਗਿਰ ਭਾਰੇ। ੧੧੧੧।","roman":"Jhoomi gire ik yau dharnee mano indr ke bajr lage gir bhaare | 1111 |","meaning_en":"","page":515}]},{"type":"verse","number":[1112],"number_text":"੧੧੧੨।","page":515,"lines":[{"gurmukhi":"ਕੋਪ ਭਰੇ ਅਸਿ ਪਾਨਿ ਧਰੇ ਧਨ ਸਿੰਘ ਅਰੇ ਗਜਰਾਜ ਸੰਘਾਰੇ।","roman":"Kop bhare asi paani dhare dhan singh are gajraaj sanghaare |","meaning_en":"","page":515},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਗਜ ਪੁੰਜ ਹੁਤੇ ਡਰ ਮਾਨਿ ਭਜੇ ਅਤਿ ਹੀ ਧੁਜਵਾਰੇ।","roman":"Aur jite gaj punj hute dar maani bhaje ati hee dhujvaare |","meaning_en":"","page":515},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਉਪਮਾ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਮਨ ਮੈ ਸੁ ਬਿਚਾਰ ਉਚਾਰੇ।","roman":"Taa chhabi kee upmaa kabi syaam kahai man mai su bichaar uchaare |","meaning_en":"","page":515},{"gurmukhi":"ਮਾਨਹੁ ਇੰਦ੍ਰ ਕੇ ਆਗਮ ਤੇ ਡਰ ਭੂ ਧਰ ਕੈ ਧਰਿ ਪੰਖ ਪਧਾਰੇ। ੧੧੧੨।","roman":"Maanhu indr ke aagam te dar bhoo dhar kai dhari pankh padhaare | 1112 |","meaning_en":"","page":515}]},{"type":"verse","number":[1113],"number_text":"੧੧੧੩।","page":515,"lines":[{"gurmukhi":"ਜੁਧ ਕੀਯੋ ਧਨ ਸਿੰਘ ਘਨੋ ਤਿਹ ਕੇ ਕੋਊ ਸਾਮੁਹਿ ਬੀਰ ਨ ਆਯੋ।","roman":"Judh keeyo dhan singh ghano tih ke ko'oo saamuhi beer na aayo |","meaning_en":"","page":515},{"gurmukhi":"ਸੋ ਰਨਿ ਕੋਪ ਸਿਉ ਆਨਿ ਪਰਿਯੋ ਨਹੀ ਜਾਨ ਦੀਯੋ ਸੋਈ ਮਾਰਿ ਗਿਰਾਯੋ।","roman":"So rani kop siu aani pariyo nahee jaan deeyo soee maari giraayo |","meaning_en":"","page":515},{"gurmukhi":"ਦਾਸਰਥੀ ਦਲ ਸਿਉ ਜਿਮਿ ਰਾਵਨ ਰੋਸ ਭਰਿਯੋ ਅਤਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Daasarthee dal siu jimi raavan ros bhariyo ati judh machaayo |","meaning_en":"","page":515},{"gurmukhi":"ਤੈਸੇ ਭਿਰਿਯੋ ਧਨ ਸਿੰਘ ਬਲੀ ਹਨਿ ਕੈ ਚਤੁਰੰਗ ਚਮੂੰ ਪੁਨਿ ਧਾਯੋ। ੧੧੧੩।","roman":"Taise bhiriyo dhan singh balee hani kai chaturang chamoon puni dhaayo | 1113 |","meaning_en":"","page":515}]},{"type":"verse","number":[1114],"number_text":"੧੧੧੪।","page":515,"lines":[{"gurmukhi":"ਟੇਰਿ ਕਹਿਯੋ ਧਨ ਸਿੰਘ ਬਲੀ ਰਨ ਤ੍ਯਾਗ ਸੁਨੋ ਹਰਿ ਭਾਜਿ ਨ ਜਈਯੈ।","roman":"Teri kahiyo dhan singh balee ran tyaag suno hari bhaaji na jaeeyai |","meaning_en":"","page":515},{"gurmukhi":"ਤਾ ਤੇ ਸੰਭਾਰ ਕੇ ਆਨਿ ਭਿਰੋ ਨਿਜ ਲੋਕਨ ਕੋ ਬਿਰਥਾ ਨ ਕਟਈਯੈ।","roman":"Taa te sanbhaar ke aani bhiro nij lokan ko birthaa na kataeeyai |","meaning_en":"","page":515},{"gurmukhi":"ਹੇ ਬਲਿਦੇਵ ਸਰਾਸਨੁ ਲੈ ਹਮ ਸੋ ਸਮੁਹਾਇ ਕੈ ਜੁਧ ਕਰਈਯੈ।","roman":"He balidev saraasnu lai ham so samuhaai kai judh karaeeyai |","meaning_en":"","page":516},{"gurmukhi":"ਸੰਗਰ ਕੇ ਸਮ ਅਉਰ ਕਛੂ ਨਹੀ ਯਾ ਤੇ ਦੁਹੂੰ ਜਗ ਮੈ ਜਸੁ ਪਈਯੈ। ੧੧੧੪।","roman":"Sangar ke sam aur kachhoo nahee yaa te duhoon jag mai jasu paeeyai | 1114 |","meaning_en":"","page":516}]},{"type":"verse","number":[1115],"number_text":"੧੧੧੫।","page":516,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਬਤੀਯਾ ਅਰਿ ਕੀ ਤਰਕੀ ਮਨ ਮੈ ਅਤਿ ਕੋਪ ਭਰਿਯੋ ਹੈ।","roman":"Yau suni kai bateeyaa ari kee tarkee man mai ati kop bhariyo hai |","meaning_en":"","page":516},{"gurmukhi":"ਬਾਲ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਕੈ ਜਦੁਬੀਰ ਹੂੰ ਧਾਇ ਪਰਿਯੋ ਹੈ।","roman":"Baal kamaan kripaan gadaa gahi kai jadubeer hoon dhaai pariyo hai |","meaning_en":"","page":516},{"gurmukhi":"ਜੁਧ ਕੇ ਫੇਰਿ ਫਿਰਿਯੋ ਧਨ ਸਿੰਘ ਸਰਾਸਨੁ ਲੈ ਨਹੀ ਨੈਕੁ ਡਰਿਯੋ ਹੈ।","roman":"Judh ke pheri phiriyo dhan singh saraasnu lai nahee naiku dariyo hai |","meaning_en":"","page":516},{"gurmukhi":"ਬਾਨਨ ਕੀ ਬਰਖਾ ਕਰਿ ਕੈ ਹਰਿ ਸਿਉ ਲਰਿ ਕੈ ਬਲਿ ਸਾਥ ਅਰਿਯੋ ਹੈ। ੧੧੧੫।","roman":"Baanan kee barkhaa kari kai hari siu lari kai bali saath ariyo hai | 1115 |","meaning_en":"","page":516}]},{"type":"verse","number":[1116],"number_text":"੧੧੧੬।","page":516,"lines":[{"gurmukhi":"ਇਤ ਤੇ ਬਲਿਭਦ੍ਰ ਸੁ ਕੋਪ ਭਰਿਯੋ ਉਤ ਤੇ ਧਨ ਸਿੰਘ ਭਯੋ ਅਤਿ ਤਾਤੋ।","roman":"It te balibhadr su kop bhariyo ut te dhan singh bhayo ati taato |","meaning_en":"","page":516},{"gurmukhi":"ਜੁਧ ਕੀਯੋ ਰਿਸਿ ਘਾਇਨ ਸੋ ਸੁ ਦੁਹੂੰਨ ਕੇ ਅੰਗ ਭਯੋ ਰੰਗ ਰਾਤੋ।","roman":"Judh keeyo risi ghaain so su duhoonn ke ang bhayo rang raato |","meaning_en":"","page":516},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰੇ ਅਰਿ ਭੂਲਿ ਗਈ ਮਨ ਕੀ ਸੁਧਿ ਸਾਤੋ।","roman":"Maar hee maar pukaari pare ari bhooli gaee man kee sudhi saato |","meaning_en":"","page":516},{"gurmukhi":"ਰਾਮ ਕਹੈ ਇਹ ਭਾਤਿ ਲਰੈ ਹਰਿ ਸੋ ਹਰਿ ਜਿਉ ਗਜ ਸੋ ਗਜ ਮਾਤੋ। ੧੧੧੬।","roman":"Raam kahai ih bhaati larai hari so hari jiu gaj so gaj maato | 1116 |","meaning_en":"","page":516}]},{"type":"verse","number":[1117],"number_text":"੧੧੧੭।","page":516,"lines":[{"gurmukhi":"ਜੋ ਬਲਦੇਵ ਕਰੈ ਤਿਹ ਵਾਰ ਬਚਾਇ ਕੈ ਆਪਨੋ ਆਪੁ ਸੰਭਾਰੇ।","roman":"Jo baldev karai tih vaar bachaai kai aapno aapu sanbhaare |","meaning_en":"","page":516},{"gurmukhi":"ਲੈ ਕਰ ਮੋ ਅਸਿ ਦਉਰਿ ਤਬੈ ਕਸਿ ਕੈ ਬਲ ਊਪਰ ਘਾਇ ਪ੍ਰਹਾਰੇ।","roman":"Lai kar mo asi dauri tabai kasi kai bal oopar ghaai prahaare |","meaning_en":"","page":516},{"gurmukhi":"ਬੀਰ ਪੈ ਭੀਰ ਲਖੀ ਜਦੁਬੀਰ ਸੁ ਜਾਦਵ ਲੈ ਰਿਪੁ ਓਰ ਸਿਧਾਰੇ।","roman":"Beer pai bheer lakhee jadubeer su jaadav lai ripu or sidhaare |","meaning_en":"","page":516},{"gurmukhi":"ਘੇਰਿ ਲਯੋ ਧਨ ਸਿੰਘ ਤਬੈ ਨਿਸ ਮੈ ਸਸਿ ਕੀ ਢਿਗ ਜਿਉ ਲਖ ਤਾਰੇ। ੧੧੧੭।","roman":"Gheri layo dhan singh tabai nis mai sasi kee dhig jiu lakh taare | 1117 |","meaning_en":"","page":516}]},{"type":"verse","number":[1118],"number_text":"੧੧੧੮।","page":516,"lines":[{"gurmukhi":"ਬੇੜਿ ਲਯੋ ਧਨ ਸਿੰਘ ਜਬੈ ਗਜ ਸਿੰਘ ਜੁ ਠਾਢੌ ਹੁਤੋ ਸੋਊ ਧਾਯੋ।","roman":"Beri layo dhan singh jabai gaj singh ju thaadhau huto so'oo dhaayo |","meaning_en":"","page":516},{"gurmukhi":"ਸ੍ਰੀ ਬਲਦੇਵ ਲਖਿਯੋ ਤਬ ਹੀ ਚੜਿ ਸਯੰਦਨ ਵਾਹੀ ਕੀ ਓਰਿ ਧਵਾਯੋ।","roman":"Sree baldev lakhiyo tab hee chari sayandan vaahee kee ori dhavaayo |","meaning_en":"","page":516},{"gurmukhi":"ਆਵਨ ਸੋ ਨ ਦਯੋ ਹਰਿ ਲਉ ਅਧ ਬੀਚ ਹੀ ਬਾਨਨ ਸੋ ਬਿਰਮਾਯੋ।","roman":"Aavan so na dayo hari lau adh beech hee baanan so birmaayo |","meaning_en":"","page":516},{"gurmukhi":"ਠਾਢੋ ਰਹਿਯੋ ਗਜਸਿੰਘ ਤਹਾ ਸੁ ਮਨੋ ਗਜ ਕੇ ਪਗਿ ਸਾਕਰ ਪਾਯੋ। ੧੧੧੮।","roman":"Thaadho rahiyo gajsingh tahaa su mano gaj ke pagi saakar paayo | 1118 |","meaning_en":"","page":516}]},{"type":"verse","number":[1119],"number_text":"੧੧੧੯।","page":516,"lines":[{"gurmukhi":"ਧਨਸਿੰਘ ਸੋ ਸ੍ਰੀ ਹਰਿ ਜੁਧੁ ਕਰੇ ਕਬਿ ਰਾਮ ਕਹੈ ਕਹੂੰ ਜਾਤ ਨ ਮਾਰਿਯੋ।","roman":"Dhansingh so sree hari judhu kare kabi raam kahai kahoon jaat na maariyo |","meaning_en":"","page":516},{"gurmukhi":"ਕੋਪ ਭਰਿਯੋ ਮਧੁ ਸੂਦਨ ਜੂ ਕਰ ਬੀਚ ਸੁ ਆਪਨੇ ਚਕ੍ਰ ਸੰਭਾਰਿਯੋ।","roman":"Kop bhariyo madhu soodan joo kar beech su aapne chakr sanbhaariyo |","meaning_en":"","page":516},{"gurmukhi":"ਛਾਡਿ ਦਯੋ ਰਨ ਮੈ ਬਰ ਕੈ ਧਨ ਸਿੰਘ ਕੋ ਕਾਟਿ ਕੈ ਸੀਸ ਉਤਾਰਿਯੋ।","roman":"Chhaadi dayo ran mai bar kai dhan singh ko kaati kai sees utaariyo |","meaning_en":"","page":516},{"gurmukhi":"ਯੌ ਤਰਫਿਯੋ ਧਰ ਭੂਮਿ ਬਿਖੈ ਮਨੋ ਮੀਨ ਸਰੋਵਰ ਤੇ ਗਹਿ ਡਾਰਿਯੋ। ੧੧੧੯।","roman":"Yau tarphiyo dhar bhoomi bikhai mano meen sarovar te gahi daariyo | 1119 |","meaning_en":"","page":516}]},{"type":"verse","number":[1120],"number_text":"੧੧੨੦।","page":516,"lines":[{"gurmukhi":"ਮਾਰਿ ਲਯੋ ਧਨ ਸਿੰਘ ਜਬੈ ਤਬ ਹੀ ਲਖਿ ਜਾਦਵ ਸੰਖ ਬਜਾਏ।","roman":"Maari layo dhan singh jabai tab hee lakhi jaadav sankh bajaae |","meaning_en":"","page":516},{"gurmukhi":"ਕੇਤਕ ਬੀਰ ਕਟੇ ਬਿਕਟੇ ਹਰਿ ਸੋ ਲਰਿ ਕੈ ਹਰਿ ਲੋਕਿ ਸਿਧਾਏ।","roman":"Ketak beer kate bikte hari so lari kai hari loki sidhaae |","meaning_en":"","page":516},{"gurmukhi":"ਠਾਢੋ ਹੁਤੋ ਗਜ ਸਿੰਘ ਜਹਾ ਯਹ ਕਉਤੁਕ ਦੇਖ ਮਹਾ ਬਿਸਮਾਏ।","roman":"Thaadho huto gaj singh jahaa yah kautuk dekh mahaa bismaae |","meaning_en":"","page":516},{"gurmukhi":"ਤਉ ਲਗਿ ਭਾਗਲਿ ਆਇ ਕਹਿਯੋ ਜੋ ਰਹੇ ਭਜਿ ਕੈ ਤੁਮਰੇ ਪਹਿ ਆਏ। ੧੧੨੦।","roman":"Tau lagi bhaagli aai kahiyo jo rahe bhaji kai tumre pahi aae | 1120 |","meaning_en":"","page":516}]},{"type":"verse","number":[1121],"number_text":"੧੧੨੧।","page":517,"lines":[{"gurmukhi":"ਯੌ ਸੁਨ ਕੈ ਤਿਨ ਕੇ ਮੁਖ ਤੇ ਗਜ ਸਿੰਘ ਬਲੀ ਅਤਿ ਕੋਪ ਭਰਿਯੋ।","roman":"Yau sun kai tin ke mukh te gaj singh balee ati kop bhariyo |","meaning_en":"","page":517},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਨਿਹਾਰ ਕੈ ਰਾਮ ਕੀ ਓਰਿ ਧਵਾਇ ਤਹਾ ਰਥੁ ਜਾਇ ਪਰਿਯੋ।","roman":"Kabi syaam nihaar kai raam kee ori dhavaai tahaa rathu jaai pariyo |","meaning_en":"","page":517},{"gurmukhi":"ਤਜਿ ਸੰਕ ਨਿਸੰਕ ਹੁਇ ਜੁਧ ਕਰਿਯੋ ਜਦੁਬੀਰ ਕਹਾ ਤਿਨ ਯੌ ਉਚਰਿਯੋ।","roman":"Taji sank nisank hui judh kariyo jadubeer kahaa tin yau uchriyo |","meaning_en":"","page":517},{"gurmukhi":"ਧਨਿ ਹੈ ਧਨ ਸਿੰਘ ਬਲੀ ਹਰਿ ਕੇ ਸਮੁਹੇ ਲਰਿ ਕੈ ਭਵ ਸਿੰਧ ਤਰਿਯੋ। ੧੧੨੧।","roman":"Dhani hai dhan singh balee hari ke samuhe lari kai bhav sindh tariyo | 1121 |","meaning_en":"","page":517}]},{"type":"verse","number":[1122],"number_text":"੧੧੨੨।","page":517,"lines":[{"gurmukhi":"ਪ੍ਰੇਮ ਸੋ ਯੌ ਕਹਿ ਕੈ ਮੁਖ ਤੇ ਪਰਲੋਕ ਸੁ ਲੋਕ ਰਹੇ ਸੁ ਬਿਚਾਰਿਯੋ।","roman":"Prem so yau kahi kai mukh te parlok su lok rahe su bichaariyo |","meaning_en":"","page":517},{"gurmukhi":"ਤੇਜ ਪ੍ਰਚੰਡ ਬਡੋ ਬਰਛਾ ਰਿਸ ਕੈ ਕਰਿ ਮੈ ਗਜ ਸਿੰਘ ਸੰਭਾਰਿਯੋ।","roman":"Tej prachand bado barchhaa ris kai kari mai gaj singh sanbhaariyo |","meaning_en":"","page":517},{"gurmukhi":"ਜਾਹੁ ਕਹਾ ਬਲਭਦ੍ਰ ਅਬੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਇਹ ਭਾਤਿ ਉਚਾਰਿਯੋ।","roman":"Jaahu kahaa balbhadr abai kabi syaam kahai ih bhaati uchaariyo |","meaning_en":"","page":517},{"gurmukhi":"ਸੋ ਬਰ ਕੈ ਕਰ ਕੋ ਤਨ ਕੋ ਜਦੁਬੀਰ ਕੇ ਭ੍ਰਾਤ ਕੇ ਊਪਰਿ ਡਾਰਿਯੋ। ੧੧੨੨।","roman":"So bar kai kar ko tan ko jadubeer ke bhraat ke oopri daariyo | 1122 |","meaning_en":"","page":517}]},{"type":"verse","number":[1123],"number_text":"੧੧੨੩।","page":517,"lines":[{"gurmukhi":"ਆਵਤ ਇਉ ਬਰਛਾ ਗਹਿ ਕੈ ਬਲਦੇਵ ਸੁ ਏਕ ਉਪਾਇ ਕਰਿਯੋ ਹੈ।","roman":"Aavat iu barchhaa gahi kai baldev su ek upaai kariyo hai |","meaning_en":"","page":517},{"gurmukhi":"ਸ੍ਯੰਦਨ ਪੈ ਨਿਹੁਰਿਯੋ ਤਬ ਹੀ ਛਤ੍ਰੀ ਤਰਿ ਹੁਇ ਇਹ ਭਾਤਿ ਅਰਿਯੋ ਹੈ।","roman":"Syandan pai nihuriyo tab hee chhatree tari hui ih bhaati ariyo hai |","meaning_en":"","page":517},{"gurmukhi":"ਫੋਰਿ ਕੈ ਪਾਰਿ ਭਯੋ ਫਲ ਯੌ ਤਿਹ ਕੀ ਉਪਮਾ ਕਬਿ ਯੌ ਉਚਰਿਯੋ ਹੈ।","roman":"Phori kai paari bhayo phal yau tih kee upmaa kabi yau uchriyo hai |","meaning_en":"","page":517},{"gurmukhi":"ਮਾਨਹੁ ਕਲਿੰਦ੍ਰ ਕੇ ਸ੍ਰਿੰਗਹੁ ਤੇ ਨਿਕਸਿਯੋ ਅਹਿ ਕੋ ਫਨੁ ਕੋਪ ਭਰਿਯੋ ਹੈ। ੧੧੨੩।","roman":"Maanhu kalindr ke sringhu te niksiyo ahi ko phanu kop bhariyo hai | 1123 |","meaning_en":"","page":517}]},{"type":"verse","number":[1124],"number_text":"੧੧੨੪।","page":517,"lines":[{"gurmukhi":"ਬਲ ਸੋ ਬਲਿ ਖੈਚ ਲਯੋ ਬਰਛਾ ਤਿਹ ਕੇ ਕਰ ਸੋ ਤਿਰਛਾ ਸੁ ਭ੍ਰਮਾਯੋ।","roman":"Bal so bali khaich layo barchhaa tih ke kar so tirchhaa su bhramaayo |","meaning_en":"","page":517},{"gurmukhi":"ਯੌ ਚਮਕਿਯੋ ਦਮਕਿਯੋ ਨਭ ਮੈ ਚੁਟੀਆ ਉਡ ਤੇਜੁ ਮਨੋ ਦਰਸਾਯੋ।","roman":"Yau chamkiyo damkiyo nabh mai chuteeaa ud teju mano darsaayo |","meaning_en":"","page":517},{"gurmukhi":"ਸ੍ਰੀ ਬਲਭਦ੍ਰ ਅਯੋਧਨ ਮੈ ਰਿਸ ਕੈ ਗਜ ਸਿੰਘ ਕੀ ਓਰਿ ਚਲਾਯੋ।","roman":"Sree balbhadr ayodhan mai ris kai gaj singh kee ori chalaayo |","meaning_en":"","page":517},{"gurmukhi":"ਮਾਨਹੁ ਕਾਲ ਪਰੀਛਤ ਕਉ ਜਮਦੰਡ ਪ੍ਰਚੰਡ ਕਿਧੋ ਚਮਕਾਯੋ। ੧੧੨੪।","roman":"Maanhu kaal pareechhat kau jamdand prachand kidho chamkaayo | 1124 |","meaning_en":"","page":517}]},{"type":"verse","number":[1125],"number_text":"੧੧੨੫।","page":517,"lines":[{"gurmukhi":"ਗਜ ਸਿੰਘ ਅਨੇਕ ਉਪਾਇ ਕੀਏ ਨ ਬਚਿਯੋ ਉਰਿ ਆਇ ਲਗਿਯੋ ਬਰਛਾ ਬਰਿ।","roman":"Gaj singh anek upaai kee'e na bachiyo uri aai lagiyo barchhaa bari |","meaning_en":"","page":517},{"gurmukhi":"ਭੂਪ ਬਿਲੋਕਤ ਹੈ ਸਿਗਰੇ ਧੁਨਿ ਸੀਸ ਹਹਾ ਕਹਿ ਮੀਚਤ ਹੈ ਕਰ।","roman":"Bhoop bilokat hai sigre dhuni sees hahaa kahi meechat hai kar |","meaning_en":"","page":517},{"gurmukhi":"ਘਾਉ ਪ੍ਰਚੰਡ ਲਗਿਯੋ ਤਿਹ ਕੋ ਮੁਰਛਾਇ ਪਰਿਯੋ ਨ ਤਜ੍ਯੋ ਕਰ ਤੇ ਸਰ।","roman":"Ghaau prachand lagiyo tih ko murchhaai pariyo na tajyo kar te sar |","meaning_en":"","page":517},{"gurmukhi":"ਸ੍ਯੰਦਨ ਪੈ ਗਜ ਸਿੰਘ ਗਿਰਿਯੋ ਗਿਰਿ ਊਪਰਿ ਜਿਉ ਗਜਰਾਜ ਕਲੇਵਰ। ੧੧੨੫।","roman":"Syandan pai gaj singh giriyo giri oopri jiu gajraaj kalevar | 1125 |","meaning_en":"","page":517}]},{"type":"verse","number":[1126],"number_text":"੧੧੨੬।","page":517,"lines":[{"gurmukhi":"ਚੇਤ ਭਯੋ ਤਬ ਹੀ ਗਜ ਸਿੰਘ ਸੰਭਾਰਿ ਪ੍ਰਚੰਡ ਕੁਵੰਡ ਚਲਾਯੋ।","roman":"Chet bhayo tab hee gaj singh sanbhaari prachand kuvand chalaayo |","meaning_en":"","page":517},{"gurmukhi":"ਕਾਨ ਪ੍ਰਮਾਨ ਲਉ ਖੈਚ ਕੇ ਆਨਿ ਸੁ ਤਾਨ ਕੈ ਬਾਨ ਪ੍ਰਕੋਪ ਚਲਾਯੋ।","roman":"Kaan pramaan lau khaich ke aani su taan kai baan prakop chalaayo |","meaning_en":"","page":517},{"gurmukhi":"ਏਕ ਤੇ ਹੁਇ ਕੈ ਅਨੇਕ ਚਲੇ ਤਿਹ ਕੀ ਉਪਮਾ ਕਹੁ ਭਾਖਿ ਸੁਨਾਯੋ।","roman":"Ek te hui kai anek chale tih kee upmaa kahu bhaakhi sunaayo |","meaning_en":"","page":517},{"gurmukhi":"ਪਉਨ ਕੇ ਭਛਕ ਤਛਕ ਲਛਕ ਲੈ ਬਲਿ ਕੀ ਸਰਨਾਗਤਿ ਆਯੋ। ੧੧੨੬।","roman":"Paun ke bhachhak tachhak lachhak lai bali kee sarnaagti aayo | 1126 |","meaning_en":"","page":517}]},{"type":"verse","number":[1127],"number_text":"੧੧੨੭।","page":517,"lines":[{"gurmukhi":"ਬਾਨ ਨ ਏਕ ਲਗਿਯੋ ਬਲਿ ਕੋ ਗਜ ਸਿੰਘ ਤਬੈ ਇਹ ਭਾਤਿ ਕਹਿਯੋ ਹੈ।","roman":"Baan na ek lagiyo bali ko gaj singh tabai ih bhaati kahiyo hai |","meaning_en":"","page":517},{"gurmukhi":"ਸੇਸ ਸੁਰੇਸ ਧਨੇਸ ਦਿਨੇਸ ਮਹੇਸ ਨਿਸੇਸ ਖਗੇਸ ਗਹਿਯੋ ਹੈ।","roman":"Ses sures dhanes dines mahes nises khages gahiyo hai |","meaning_en":"","page":517},{"gurmukhi":"ਜੁਧ ਬਿਖੈ ਅਬ ਲਉ ਸੁਨਿ ਲੈ ਸੋਊ ਬੀਰ ਹਨ੍ਯੋ ਮਨ ਮੈ ਜੁ ਚਹਿਯੋ ਹੈ।","roman":"Judh bikhai ab lau suni lai so'oo beer hanyo man mai ju chahiyo hai |","meaning_en":"","page":517},{"gurmukhi":"ਏਕ ਅਚੰਭਵ ਹੈ ਮੁਹਿ ਦੇਖਤ ਤੋ ਤਨ ਮੈ ਕਸ ਜੀਵ ਰਹਿਯੋ ਹੈ। ੧੧੨੭।","roman":"Ek achanbhav hai muhi dekhat to tan mai kas jeev rahiyo hai | 1127 |","meaning_en":"","page":517}]},{"type":"verse","number":[1128],"number_text":"੧੧੨੮।","page":518,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਬਤੀਯਾ ਬਲਿ ਸੋ ਬਰਛਾ ਧੁਜ ਸੰਜੁਤ ਖੈਚਿ ਚਲਾਯੋ।","roman":"Yau kahi kai bateeyaa bali so barchhaa dhuj sanjut khaichi chalaayo |","meaning_en":"","page":518},{"gurmukhi":"ਤਉ ਧਨੁ ਲੈ ਕਰਿ ਮੈ ਮੁਸਲੀ ਸੋਊ ਆਵਤ ਨੈਨਨ ਸੋ ਲਖਿ ਪਾਯੋ।","roman":"Tau dhanu lai kari mai muslee so'oo aavat nainan so lakhi paayo |","meaning_en":"","page":518},{"gurmukhi":"ਉਗ੍ਰ ਪਰਾਕ੍ਰਮ ਕੈ ਸੰਗ ਬਾਨ ਅਚਾਨਕ ਸੋ ਕਟਿ ਭੂਮਿ ਗਿਰਾਯੋ।","roman":"Ugr paraakram kai sang baan achaanak so kati bhoomi giraayo |","meaning_en":"","page":518},{"gurmukhi":"ਮਾਨਹੁ ਪੰਖਨ ਕੋ ਅਹਿਵਾ ਖਗਰਾਜ ਕੇ ਹਾਥਿ ਪਰਿਯੋ ਰਿਸਿ ਘਾਯੋ। ੧੧੨੮।","roman":"Maanhu pankhan ko ahivaa khagraaj ke haathi pariyo risi ghaayo | 1128 |","meaning_en":"","page":518}]},{"type":"verse","number":[1129],"number_text":"੧੧੨੯।","page":518,"lines":[{"gurmukhi":"ਕੋਪ ਭਰਿਯੋ ਅਤਿ ਹੀ ਗਜ ਸਿੰਘ ਲਯੋ ਬਰਛਾ ਅਰਿ ਓਰ ਚਲਾਯੋ।","roman":"Kop bhariyo ati hee gaj singh layo barchhaa ari or chalaayo |","meaning_en":"","page":518},{"gurmukhi":"ਜਾਇ ਲਗਿਯੋ ਮੁਸਲੀਧਰ ਕੇ ਤਨਿ ਲਾਗਤ ਤਾ ਅਤਿ ਹੀ ਦੁਖ ਪਾਯੋ।","roman":"Jaai lagiyo musleedhar ke tani laagat taa ati hee dukh paayo |","meaning_en":"","page":518},{"gurmukhi":"ਪਾਰਿ ਪ੍ਰਚੰਡ ਭਯੋ ਫਲ ਯੌ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਮਨ ਮੈ ਇਹ ਆਯੋ।","roman":"Paari prachand bhayo phal yau jasu taa chhabi ko man mai ih aayo |","meaning_en":"","page":518},{"gurmukhi":"ਮਾਨਹੁ ਗੰਗ ਕੀ ਧਾਰ ਕੇ ਮਧਿ ਉਤੰਗ ਹੁਇ ਕੂਰਮ ਸੀਸ ਉਚਾਯੋ। ੧੧੨੯।","roman":"Maanhu gang kee dhaar ke madhi utang hui kooram sees uchaayo | 1129 |","meaning_en":"","page":518}]},{"type":"verse","number":[1130],"number_text":"੧੧੩੦।","page":518,"lines":[{"gurmukhi":"ਲਾਗਤ ਸਾਂਗ ਕੀ ਸ੍ਰੀ ਬਲਭਦ੍ਰ ਸੁ ਸਯੰਦਨ ਤੇ ਗਹਿ ਖੈਚ ਕਢਿਯੋ।","roman":"Laagat saang kee sree balbhadr su sayandan te gahi khaich kadhiyo |","meaning_en":"","page":518},{"gurmukhi":"ਮੁਰਝਾਇ ਕੈ ਭੂਮਿ ਪਰਿਯੋ ਨ ਮਰਿਯੋ ਸੁਰ ਬ੍ਰਿਛ ਗਿਰਿਯੋ ਮਨੋ ਜੋਤਿ ਮਢਿਯੋ।","roman":"Murjhaai kai bhoomi pariyo na mariyo sur brichh giriyo mano joti madhiyo |","meaning_en":"","page":518},{"gurmukhi":"ਜਬ ਚੇਤ ਭਯੋ ਭ੍ਰਮ ਛੂਟਿ ਗਯੋ ਉਠਿ ਠਾਢੋ ਭਯੋ ਮਨਿ ਕੋਪੁ ਬਢਿਯੋ।","roman":"Jab chet bhayo bhram chhooti gayo uthi thaadho bhayo mani kopu badhiyo |","meaning_en":"","page":518},{"gurmukhi":"ਰਥ ਹੇਰ ਕੈ ਧਾਇ ਚੜਿਯੋ ਬਰ ਸੋ ਗਿਰਿ ਪੈ ਮਨੋ ਕੂਦ ਕੈ ਸਿੰਘ ਚਢਿਯੋ। ੧੧੩੦।","roman":"Rath her kai dhaai chariyo bar so giri pai mano kood kai singh chadhiyo | 1130 |","meaning_en":"","page":518}]},{"type":"verse","number":[1131],"number_text":"੧੧੩੧।","page":518,"lines":[{"gurmukhi":"ਪੁਨਿ ਆਇ ਭਿਰਿਯੋ ਗਜ ਸਿੰਘ ਸੋ ਬੀਰ ਬਲੀ ਮਨ ਮੈ ਨਹੀ ਨੈਕੁ ਡਰਿਯੋ।","roman":"Puni aai bhiriyo gaj singh so beer balee man mai nahee naiku dariyo |","meaning_en":"","page":518},{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਕ੍ਰਿਪਾਨ ਗਦਾ ਰਿਸਿ ਬੀਚ ਅਯੋਧਨ ਜੁਧ ਕਰਿਯੋ।","roman":"Dhanu baan sanbhaari kripaan gadaa risi beech ayodhan judh kariyo |","meaning_en":"","page":518},{"gurmukhi":"ਜੋਊ ਆਵਤ ਭਯੋ ਸਰੁ ਸਤ੍ਰਨ ਕੋ ਸੰਗਿ ਬਾਨਨ ਕੇ ਸੋਊ ਕਾਟਿ ਡਰਿਯੋ।","roman":"Jo'oo aavat bhayo saru satran ko sangi baanan ke so'oo kaati dariyo |","meaning_en":"","page":518},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬਲਦੇਵ ਮਹਾਰਨ ਕੀ ਛਿਤ ਤੇ ਨਹੀ ਪੈਗ ਟਰਿਯੋ। ੧੧੩੧।","roman":"Kabi syaam kahai baldev mahaaran kee chhit te nahee paig tariyo | 1131 |","meaning_en":"","page":518}]},{"type":"verse","number":[1132],"number_text":"੧੧੩੨।","page":518,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਹਲ ਮੂਸਲ ਲੈ ਕਰ ਮੈ ਅਰਿ ਸਿਉ ਅਰ ਕੈ ਅਤਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Bahuro hal moosal lai kar mai ari siu ar kai ati judh machaayo |","meaning_en":"","page":518},{"gurmukhi":"ਲੈ ਬਰਛਾ ਗਜ ਸਿੰਘ ਬਲੀ ਬਲਿ ਸਿਉ ਬਲਿਦੇਵ ਕੀ ਓਰਿ ਚਲਾਯੋ।","roman":"Lai barchhaa gaj singh balee bali siu balidev kee ori chalaayo |","meaning_en":"","page":518},{"gurmukhi":"ਆਵਤ ਸੋ ਲਖਿ ਕੈ ਫਲ ਕੋ ਹਲ ਕਟਿ ਕੈ ਪੁਨ ਭੂਮਿ ਗਿਰਾਯੋ।","roman":"Aavat so lakhi kai phal ko hal kati kai pun bhoomi giraayo |","meaning_en":"","page":518},{"gurmukhi":"ਸੋ ਫਲ ਹੀਨ ਭਯੋ ਜਬ ਹੀ ਕਸ ਕੈ ਬਲਿਭਦ੍ਰ ਕੇ ਗਾਤਿ ਲਗਾਯੋ। ੧੧੩੨।","roman":"So phal heen bhayo jab hee kas kai balibhadr ke gaati lagaayo | 1132 |","meaning_en":"","page":518}]},{"type":"verse","number":[1133],"number_text":"੧੧੩੩।","page":518,"lines":[{"gurmukhi":"ਖਗ ਕਰੰ ਗਹਿ ਕੈ ਗਜ ਸਿੰਘ ਅਨੰਤ ਕੇ ਊਪਰਿ ਕੋਪਿ ਚਲਾਯੋ।","roman":"Khag karan gahi kai gaj singh anant ke oopri kopi chalaayo |","meaning_en":"","page":518},{"gurmukhi":"ਤਉ ਮਸਲੀ ਕਰਿ ਚਰਮ ਲੀਯੋ ਧਰਿ ਯੌ ਅਰਿ ਕਉ ਬਲਿ ਘਾਉ ਬਚਾਯੋ।","roman":"Tau maslee kari charam leeyo dhari yau ari kau bali ghaau bachaayo |","meaning_en":"","page":518},{"gurmukhi":"ਢਾਲ ਕੇ ਫੂਲ ਪੈ ਧਾਰ ਬਹੀ ਚਿਨਗਾਰ ਉਠੀ ਕਬਿ ਯੌ ਗੁਨ ਗਾਯੋ।","roman":"Dhaal ke phool pai dhaar bahee chingaar uthee kabi yau gun gaayo |","meaning_en":"","page":518},{"gurmukhi":"ਮਾਨਹੁ ਪਾਵਸ ਕੀ ਨਿਸਿ ਮੈ ਬਿਜੁਰੀ ਦੁਤਿ ਤਾਰਨ ਕੋ ਪ੍ਰਗਟਾਯੋ। ੧੧੩੩।","roman":"Maanhu paavas kee nisi mai bijuree duti taaran ko pragtaayo | 1133 |","meaning_en":"","page":518}]},{"type":"verse","number":[1134],"number_text":"੧੧੩੪।","page":518,"lines":[{"gurmukhi":"ਘਾਇ ਹਲੀ ਸਹਿ ਕੈ ਰਿਪੁ ਕੋ ਗਹਿ ਕੈ ਕਰਵਾਰ ਸੁ ਬਾਰ ਕਰਿਯੋ ਹੈ।","roman":"Ghaai halee sahi kai ripu ko gahi kai karvaar su baar kariyo hai |","meaning_en":"","page":518},{"gurmukhi":"ਧਾਰ ਬਹੀ ਅਰਿ ਕੰਠਿ ਬਿਖੈ ਕਟਿ ਕੈ ਤਿਹ ਕੋ ਸਿਰੁ ਭੂਮਿ ਝਰਿਯੋ ਹੈ।","roman":"Dhaar bahee ari kanthi bikhai kati kai tih ko siru bhoomi jhariyo hai |","meaning_en":"","page":518},{"gurmukhi":"ਬਜ੍ਰ ਜਰੇ ਰਥ ਤੇ ਗਿਰਿਯੋ ਤਿਹ ਕੋ ਜਸੁ ਯੌ ਕਬਿ ਨੈ ਉਚਰਿਯੋ ਹੈ।","roman":"Bajr jare rath te giriyo tih ko jasu yau kabi nai uchriyo hai |","meaning_en":"","page":518},{"gurmukhi":"ਮਾਨਹੁ ਤਾਰਨ ਲੋਕ ਹੂੰ ਤੇ ਸੁਰ ਭਾਨੁ ਹਨ੍ਯੋ ਸਿਰ ਭੂਮਿ ਪਰਿਯੋ ਹੈ। ੧੧੩੪।","roman":"Maanhu taaran lok hoon te sur bhaanu hanyo sir bhoomi pariyo hai | 1134 |","meaning_en":"","page":518}]},{"type":"verse","number":[1135],"number_text":"੧੧੩੫।","page":519,"lines":[{"gurmukhi":"ਮਾਰਿ ਲਯੋ ਗਜ ਸਿੰਘ ਜਬੈ ਤਜਿ ਕੈ ਰਨ ਕੋ ਸਭ ਹੀ ਭਟ ਭਾਗੇ।","roman":"Maari layo gaj singh jabai taji kai ran ko sabh hee bhat bhaage |","meaning_en":"","page":519},{"gurmukhi":"ਸ੍ਰਉਨ ਭਰੇ ਲਖਿ ਲੋਥ ਡਰੇ ਨਹਿ ਧੀਰ ਧਰੇ ਨਿਸ ਕੇ ਜਨੁ ਜਾਗੇ।","roman":"Sraun bhare lakhi loth dare nahi dheer dhare nis ke janu jaage |","meaning_en":"","page":519},{"gurmukhi":"ਮਾਰਿ ਲਏ ਨ੍ਰਿਪ ਪੰਚ ਭਗੇ ਤਿਨ ਯੌ ਕਹਿਯੋ ਜਾ ਅਪਨੇ ਪ੍ਰਭਿ ਆਗੇ।","roman":"Maari lae nrip panch bhage tin yau kahiyo jaa apne prabhi aage |","meaning_en":"","page":519},{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਦਲਿ ਧੀਰ ਛੁਟਿਯੋ ਨ੍ਰਿਪ ਹੀਯੋ ਫਟਿਯੋ ਰਿਸ ਮੈ ਅਨੁਰਾਗੇ। ੧੧੩੫।","roman":"Yau suni kai dali dheer chhutiyo nrip heeyo phatiyo ris mai anuraage | 1135 |","meaning_en":"","page":519}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਜੁਧ ਪ੍ਰਬੰਧੇ ਗਜਸਿੰਘ ਬਧਹ ਧਯਾਇ ਸਮਾਪਤੰ।","roman":"Iti sree bachitr naatak granthe krisnaavtaare judh prabandhe gajsingh badhah dhayaai samaaptan |","meaning_en":"","page":519,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}],"page":519}});
